L["1 consumable"] = "1 Verbrauchsgut"
L["1 consumable watched"] = "1 Verbrauchsgut überwacht"
L["1 craft"] = "1 Herstellung"
L["1 day"] = "1 Tag"
L["1 dungeon"] = "1 Dungeon"
L["1 hour"] = "1 Stunde"
L["1 in %d"] = "1 von %d"
L["1 item on the bar"] = "1 Gegenstand auf der Leiste"
L["1 minute"] = "1 Minute"
L["1 paladin in your group"] = "1 Paladin in deiner Gruppe"
L["1 player has their own blessing"] = "1 Spieler hat seinen eigenen Segen"
L["1 profile on this account"] = "1 Profil auf diesem Account"
L["1 raid"] = "1 Raid"
L["1 runs Naowh Forever"] = "1 nutzt Naowh Forever"
L["1 setting changed from its default"] = "1 Einstellung weicht vom Standard ab"
L["1 spell"] = "1 Zauber"
L["1 Unspent Talent Point"] = "1 nicht verteilter Talentpunkt"
L["1. PICK YOUR BARS"] = "1. WÄHLE DEINE LEISTEN"
L["100%  (default)"] = "100%  (Standard)"
L["100%, native resolution"] = "100%, native Auflösung"
L["12-hour clock"] = "12-Stunden-Uhr"
L["16x Anisotropic"] = "16x anisotrop"
L["2. ALSO KEEP"] = "2. AUSSERDEM BEHALTEN"
L["24-Hour Clock"] = "24-Stunden-Uhr"
L["24-hour clock"] = "24-Stunden-Uhr"
L["3. NAME AND SAVE"] = "3. BENENNEN UND SICHERN"
L["30, while the game is not in focus"] = "30, solange das Spiel nicht im Fokus ist"
L[": copy ID or Wowhead link"] = ": ID oder Wowhead-Link kopieren"
L[": mail expiring soon on "] = ": bald ablaufende Post bei "
L["; buys at vendors"] = "; kauft bei Händlern"
L["<AFK>"] = "<AFK>"
L["<DND>"] = "<DND>"
L["[Where?]"] = "[Wo?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Ein /thank an alle um dich herum, wenn das Spiel den Wirker nicht nennen kann."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Ein [Wo?]-Link nach dem Flüstern von jemandem, dessen Gebiet unbekannt ist. Ein Klick darauf führt ein /who für ihn aus und gibt sein Gebiet aus; seine nächsten Nachrichten werden gekennzeichnet."
L["A banner and a sound when one of them joins your group."] = "Ein Banner und ein Sound, wenn einer von ihnen deiner Gruppe beitritt."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Eine Leiste bei der Bedrohung, ab der du Aggro ziehen würdest, damit der Abstand dazu leicht abzulesen ist."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Eine Leiste für die Swings deines Ziels, neu gestartet durch jeden körperlichen Treffer, den du einsteckst, während es dich im Visier hat, und verkürzt, wenn es pariert. Das ist eine Schätzung: Das Spiel verrät nicht, wer dich womit getroffen hat, daher starten auch andere Angreifer, körperliche Spezialangriffe und Blutungsticks sie neu."
L["A bar left out is not touched by an import."] = "Eine ausgelassene Leiste bleibt bei einem Import unberührt."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Eine Leiste pro Gruppenmitglied mit Stufe und Fortschritt darin. Jedes Mitglied mit Naowh Forever teilt seine Erfahrung, auch wenn dies aus ist; alle anderen zeigen ihre Stufe. Aktualisierungen warten bis zum Kampfende. Verschiebe sie im HUD-Editor."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Eine Leiste mit Name, Abbiegepfeil und Entfernung, solange ein Wegpunkt gesetzt ist."
L["A batch of ten, four done, as it shows while you craft."] = "Eine Serie von zehn, vier fertig, wie sie beim Herstellen erscheint."
L["A black outline round the clock."] = "Ein schwarzer Umriss um die Uhr."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Ein schwarzer Umriss um die FPS-/MS-Anzeige und die Zahlen statt des weichen Schattens."
L["A black outline round the text, in place of the soft shadow."] = "Ein schwarzer Umriss um den Text statt des weichen Schattens."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Eine Schaltfläche pro Set: Klick legt es an, Umschalt-Klick speichert deine aktuelle Ausrüstung darin, Strg-Klick benennt es um, Rechtsklick ändert sein Symbol und + speichert ein neues. Das getragene Set hat einen Umriss. Verschiebe die Leiste im HUD-Editor."
L["A button that flags or unflags you for PvP, showing which you are."] = "Eine Schaltfläche, die PvP für dich ein- oder ausschaltet und zeigt, was gerade gilt."
L["A campfire in range and Camp Benefits about to run out."] = "Ein Lagerfeuer in Reichweite und die Lagervorteile laufen gleich ab."
L["A campfire in range and no Camp Benefits."] = "Ein Lagerfeuer in Reichweite, aber ohne Lagervorteile."
L["A campfire is in range"] = "Ein Lagerfeuer ist in Reichweite"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Eine Karte hinter dem Text, ein weicher dunkler Verlauf oder gar nichts."
L["A card over the pin with what it is and how far."] = "Eine Infokarte über dem Pin: was es ist und wie weit."
L["A cast part way through, swept around the ring."] = "Ein halb gewirkter Zauber, der um den Ring läuft."
L["A cast someone interrupted, held for the fade time."] = "Ein Zauber, den jemand unterbrochen hat, sichtbar bis zum Verblassen."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Ein Zauber, während deine Unterbrechung auf Abklingzeit ist, mit der Markierung, wo sie wieder bereit ist."
L["A cast while your interrupt is ready."] = "Ein Zauber, während deine Unterbrechung bereit ist."
L["A cast you cannot interrupt, with its shield."] = "Ein Zauber, den du nicht unterbrechen kannst, mit seinem Schild."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Ein Charakter erscheint hier, nachdem du dich bei eingeschalteter Instanzstatistik mit ihm eingeloggt hast. Twinks verfolgen zeigt die anderen: Erholungsbonus und Haltbarkeit, Stand ihres letzten Logins."
L["A choice among its rewards: pick this one."] = "Eine Belohnung zur Auswahl: Wähle diese."
L["A command name can only use letters, numbers and underscores."] = "Ein Befehlsname darf nur Buchstaben, Ziffern und Unterstriche enthalten."
L["A consumable or personal buff with less time than this left counts as missing."] = "Ein Verbrauchsgut oder persönlicher Buff mit weniger Restzeit als dieser gilt als fehlend."
L["A crosshair at the middle of your screen."] = "Ein Fadenkreuz in der Mitte deines Bildschirms."
L["A cup beside a healer who is drinking."] = "Ein Becher neben einem Heiler, der trinkt."
L["A custom command can't reload. Type /reload."] = "Ein eigener Befehl kann nicht neu laden. Gib /reload ein."
L["A dark or light fill and edge behind each line, or none."] = "Eine dunkle oder helle Füllung mit Rand hinter jeder Zeile oder keine."
L["A dark panel behind the icons."] = "Eine dunkle Fläche hinter den Symbolen."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Eine Tür auf jedem Dungeon- und Raideingang auf der Weltkarte, für die Fraktionen, die das Journal zeigt. Fahre mit der Maus darüber für die Stufen, klicke darauf für einen Wegpunkt."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Ein Punkt auf einem Platz, wo eine bessere Verzauberung für deine Stufe wartet: Fahre mit der Maus darüber für den Rat, klicke darauf, um im Handelskanal zu fragen."
L["A fading trail behind the cursor."] = "Eine verblassende Spur hinter dem Mauszeiger."
L["A few quick steps for %s only, its own modules included."] = "Ein paar schnelle Schritte nur für %s, eigene Module inklusive."
L["A game that opens when a flight starts and closes when you land."] = "Ein Spiel, das sich beim Flugstart öffnet und schließt, wenn du landest."
L["A gear set called %s already exists."] = "Ein Set namens %s existiert bereits."
L["A glow on the moving edge of the fill."] = "Ein Leuchten an der wandernden Kante der Füllung."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Eine versteckte Questreihe quer durch Azeroth: Klicke nacheinander auf jedes Ding in der Welt. Sie bringt viel Erfahrung und endet beim Gemütlichen Schlafsack; ruhe darin für einen Erfahrungsbonus."
L["A key that opens Group Inspect."] = "Eine Taste, die die Gruppenübersicht öffnet."
L["A key that shows a boss's loot at your cursor."] = "Eine Taste, die die Beute eines Bosses an deinem Mauszeiger zeigt."
L["A key that uses this item."] = "Eine Taste, die diesen Gegenstand benutzt."
L["A later point needs it. "] = "Ein späterer Punkt baut darauf auf. "
L["A later step."] = "Ein späterer Schritt."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Eine Zeile für jede abgegebene Quest, mit der Erfahrung und dem Geld, die sie brachte. Belohnungsgegenstände erscheinen als eigene Zeilen."
L["A line for every reputation gain, from quests and kills alike."] = "Eine Zeile für jeden Rufgewinn, aus Quests wie aus Kills."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Eine Zeile für die Erfahrung aus jedem Kill. Questerfahrung steht in der eigenen Zeile der Quest."
L["A line from the pin down to a map pin's or corpse's spot."] = "Eine Linie vom Pin hinunter zur Stelle der Kartenmarkierung oder Leiche."
L["A line in chat with the item's link."] = "Eine Zeile im Chat mit dem Link des Gegenstands."
L["A line in their color on their player tooltip."] = "Eine Zeile in ihrer Farbe in ihrem Spieler-Tooltip."
L["A line to share them with."] = "Eine Zeile, um sie zu teilen."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Eine Zeile unter der ID, die sagt, welche Tasten sie kopieren (Strg-Umschalt-C: ID oder Wowhead-Link kopieren). Ausgeschaltet funktioniert das Tastenkürzel weiter; nur die Zeile wird nicht angezeigt."
L["A look you do not have yet|r"] = "Eine Vorlage, die du noch nicht hast|r"
L["a macro made on this character"] = "ein auf diesem Charakter erstelltes Makro"
L["A macro this character does not have yet: the import makes it."] = "Ein Makro, das dieser Charakter noch nicht hat: Der Import erstellt es."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Eine Minikarten-Schaltfläche, die %s öffnet. /nf%s macht dasselbe, und auch die Obere Leiste kann sie tragen. Wird für diesen Computer gespeichert."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Eine Naowh-Gewichtungszeile oder ein WoWSims-EP-Export (in WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Eine Naowh-Gewichtungszeile oder ein WoWSims-EP-Export."
L["A new session, before any experience."] = "Eine neue Sitzung, noch ohne Erfahrung."
L["A parry by your target took 40% off its swing."] = "Eine Parade deines Ziels hat seinen Swing um 40% verkürzt."
L["A party of five, a card each."] = "Eine Fünfergruppe, je eine Karte."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "Die Wertung eines Spielers in seinem Tooltip. Wer Naowh Forever nutzt, teilt seine; die aller anderen wird aus ihrer Ausrüstung gelesen, wenn du mit der Maus über sie fährst, in Betrachtungsreichweite und außerhalb des Kampfes."
L["A profile"] = "Ein Profil"
L["a quest"] = "eine Quest"
L["A quest reward for the other faction; try the Auction House."] = "Eine Questbelohnung der anderen Fraktion; versuche es im Auktionshaus."
L["A raid for %d players"] = "Ein Raid für %d Spieler"
L["A raid, a row each."] = "Ein Raid, je eine Zeile."
L["A rare someone else is fighting."] = "Ein seltener Gegner, den jemand anderes bekämpft."
L["A rare you have killed before."] = "Ein seltener Gegner, den du früher schon besiegt hast."
L["A rare you have not killed yet."] = "Ein seltener Gegner, den du noch nicht besiegt hast."
L["A reward from the quest "] = "Eine Belohnung der Quest "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Ein Ring um deinen Mauszeiger, damit du ihn im Kampfgetümmel nie verlierst, mit deiner globalen Abklingzeit und deinen Zaubern, die um ihn laufen."
L["A round in progress."] = "Eine laufende Runde."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Eine Symbolreihe für fehlende Buffs von Essen, Fläschchen, Elixieren und Rollen, deinen eigenen Klassenbuff und Klassenbuffs, die deiner Gruppe fehlen. Nur außerhalb des Kampfes: Im Kampf verbirgt das Spiel deine Buffs vor Addons, daher zeigen die Symbole weiter den letzten Stand. Fahre mit der Maus über eines, um einen mitgeführten Gegenstand zu wählen. Verschiebe sie im HUD-Editor."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Ein laufendes Gold pro Stunde neben der neuesten Zeile, aus Geld und Gegenstandswert seit deiner ersten Beute in dieser Sitzung."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Eine Schaltfläche Preise scannen im Auktionshaus. Sie liest jedes Angebot und merkt sich den niedrigsten Sofortkaufpreis je Gegenstand, für diesen Realm und diese Fraktion. Blizzard erlaubt einen vollständigen Scan alle 15 Minuten."
L["A junk icon on the bag slot of each item marked as junk."] = "Ein Plundersymbol auf dem Taschenplatz jedes als Plunder markierten Gegenstands."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Eine zweite Anzeige für deinen Fokus, um die Zeit von Kopfnuss oder Verwandlung auf einem Gegner im Blick zu behalten, während du einen anderen bekämpfst."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Ein Set, das von selbst angelegt wird, während du reitest oder ausruhst, und das Set, das du anhattest, kommt danach zurück."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Ein Schießspiel für Flüge: Klicke möglichst schnell auf die Völker der anderen Fraktion."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Ein kurz aufblitzender Text beim Betreten und Verlassen des Kampfes. Verschiebe ihn im HUD-Editor."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Eine kleine Leiste mit deinem nächsten Lehrerbesuch und deinem Gold, die du beim Aufsteigen offen lassen kannst. Verschiebe sie durch Ziehen."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Eine kleine Gesundheitsleiste für den anderen Tank deiner Gruppe, sichtbar, solange du tankst: Tankrolle, Bärengestalt, Verteidigungshaltung oder Zorn der Gerechtigkeit. Der andere Tank ist, wer die Tankrolle oder im Raid die Zuweisung als Haupttank hat. Klicke auf die Leiste, um ihn anzuvisieren. Änderungen im Kampf gelten, sobald der Kampf endet. Verschiebe sie im HUD-Editor."
L["A soft glow around Naowh's arrow."] = "Ein sanftes Leuchten um Naowhs Pfeil."
L["A soft glow beside each icon."] = "Ein sanftes Leuchten neben jedem Symbol."
L["A soft glow round it in your accent color."] = "Ein sanftes Leuchten um sie herum in deiner Akzentfarbe."
L["A soft glow round it in your rank's color."] = "Ein sanftes Leuchten um sie herum in der Farbe deines Rangs."
L["A soft ring pulses around each target."] = "Ein sanfter Ring pulsiert um jedes Ziel."
L["a sound to refresh"] = "Ton zum Erneuern"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Ein Sound oder der vorgelesene Sprechtext, sobald ein Zauber beginnt."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Ein Sound oder der vorgelesene Sprechtext. Text-to-Speech kann auf manchen PCs ruckeln, weil das Spiel wartet, während Windows ihn spricht; ein Sound kostet nichts."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Ein Zauber, den ein Import nicht platzieren konnte, weil du ihn noch nicht kennst, kommt beim Erlernen auf seinen gespeicherten Platz, außer du hast dort etwas anderes hingelegt."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Eine Stapeln-Schaltfläche auf der Karte, wenn angebrochene Stapel eines Gegenstands zusammengelegt werden können."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Ein Stern auf der Weltkarte für jeden seltenen Gegner, den du nicht besiegt hast, dort, wo er am wahrscheinlichsten ist. Fahre über einen für den Gegner und seine Beute, die anderen Orte, an denen er erscheint, und, falls er patrouilliert, seinen Weg; klicke darauf für einen Wegpunkt, mit Rechtsklick bleiben seine Orte und sein Weg sichtbar."
L["A string to share it with."] = "Ein String, um sie zu teilen."
L["A supporter"] = "Ein Unterstützer"
L["A team member"] = "Ein Teammitglied"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Ein Text auf der Leiste: Klicke ihn in der Vorschau an, um ihn zu ändern. Jeder Text erscheint an einer Stelle der Leiste: Wählst du einen, der woanders steht, wandert er hierher."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Eine Markierung auf der Leiste, wo die Abklingzeit deiner Unterbrechung endet. Ausgeblendet, solange sie bereit ist."
L["A title bar naming the mob the threat is on."] = "Eine Titelleiste mit dem Namen des Gegners, auf dem die Bedrohung liegt."
L["A trained spell drops into its saved slot."] = "Ein erlernter Zauber landet auf seinem gespeicherten Platz."
L["a vendor sells the formula"] = "ein Händler verkauft die Formel"
L["A warning when a rare is near"] = "Eine Warnung, wenn ein seltener Gegner in der Nähe ist"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Eine Warnung, wenn ein seltener Gegner in deiner Nähe ist: wenn seine Namensplakette erscheint, du mit der Maus darüberfährst oder ihn ins Ziel nimmst. Eine Warnkarte mit seinem Porträt: Ein Rechtsklick schließt sie, und ihr Pin setzt einen Wegpunkt zum seltenen Gegner. Verschiebe sie im HUD-Editor."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Eine Warnung, solange ein Jäger oder Hexenmeister keinen Begleiter dabeihat. Ein Hexenmeister, der seinen Dämon geopfert hat, wird nicht gewarnt. Verschiebe sie im HUD-Editor."
L["A word of your own on the icon."] = "Ein eigenes Wort auf dem Symbol."
L["A world drop from %d kinds of mob"] = "Ein Weltdrop von %d |4Gegnerart:Gegnerarten;"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Ein WoW-Quiz für Lagerfeuer und Flüge oder jederzeit mit /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Ein gelbes ! auf der Weltkarte bei jedem Questgeber mit einer Quest, die du annehmen kannst und die noch Erfahrung gibt. Fahre darüber für die Quests; klicke darauf für einen Wegpunkt."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Ein älteres Gebiet wird nicht mehr angezeigt, da der Spieler wohl weitergezogen ist."
L["Abandon %s?"] = "%s abbrechen?"
L["Abilities"] = "Fähigkeiten"
L["about "] = "etwa "
L["about %d:%02d"] = "etwa %d:%02d"
L["About %s at your last scan%s%s"] = "Etwa %s beim letzten Scan%s%s"
L["About %s spent"] = "Etwa %s ausgegeben"
L["About a minute."] = "Etwa eine Minute."
L["Above"] = "Darüber"
L["Acc."] = "Präz."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Akzent: Klassensegen fehlt. Heller: läuft aus. Dunkler: nur Spieler mit eigenem Segen."
L["Accept Quests"] = "Quests annehmen"
L["Accept Shared Dungeon Quests"] = "Geteilte Dungeonquests annehmen"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Nimmt eine Quest an, sobald ihr Text erscheint. Nutze die Zusatztaste, um sie erst zu lesen."
L["Accepts dungeon quests your group shares with you straight away."] = "Nimmt Dungeonquests, die deine Gruppe mit dir teilt, sofort an."
L["Accepts shared quests"] = "Nimmt geteilte Quests an"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Nimmt die Abfrage auf dem Bildschirm an: eine Beschwörung, eine Wiederbelebung, eine Gruppeneinladung."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Nimmt Quests für dich an, gibt sie ab und teilt sie und merkt sich die Belohnung, die du für eine Quest gespeichert hast. Die Zusatztaste überspringt sie oder löst sie aus, wie unter Zusatztaste bewirkt eingestellt."
L["Account"] = "Account"
L["Account "] = "Account "
L["Account macros"] = "Accountweite Makros"
L["Account this hour: %d of %d"] = "Account in dieser Stunde: %d von %d"
L["Accuracy"] = "Genauigkeit"
L["Action Bars is switched off."] = "Aktionsleisten ist ausgeschaltet."
L["Action Bars' own window, with your class's saved sets."] = "Das eigene Fenster von Aktionsleisten mit den gespeicherten Sets deiner Klasse."
L["Active"] = "Aktiv"
L["Activity Bar"] = "Aktivitätsleiste"
L["Activity Bar Color"] = "Farbe der Aktivitätsleiste"
L["Activity Bar Height"] = "Höhe der Aktivitätsleiste"
L["Add %d item to your junk list: %s%s?"] = "%d Gegenstand zu deiner Plunderliste hinzufügen: %s%s?"
L["Add %d items to your junk list: %s%s?"] = "%d Gegenstände zu deiner Plunderliste hinzufügen: %s%s?"
L["Add %d macro as character macros?%s"] = "%d Makro als Charaktermakro hinzufügen?%s"
L["Add %d macros as character macros?%s"] = "%d Makros als Charaktermakros hinzufügen?%s"
L["Add %s"] = "%s hinzufügen"
L["Add %s (%d items) as a new BiS list?"] = "%s (%d Gegenstände) als neue BiS-Liste hinzufügen?"
L["Add %s to the Consumable Bar?"] = "%s zur Verbrauchsleiste hinzufügen?"
L["Add a backup pick"] = "Ersatzfavoriten hinzufügen"
L["Add a Button"] = "Schaltfläche einfügen"
L["Add a stat"] = "Wert hinzufügen"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Füge eine Gegenstands-ID hinzu oder importiere eine Liste. Bei Essen zählt jeder Satt-Buff, bei anderen Gegenständen ihr eigener Buff; füge Buff-Zauber-IDs nur für einen Gegenstand hinzu, der einen anderen gibt. Nichts wird automatisch hinzugefügt. Fahre mit der Maus über eine Erinnerung, um einen eingerichteten Gegenstand aus deinen Taschen zu wählen. Erinnerungen pausieren im Kampf; Gegenstandsmenüs funktionieren außerhalb des Kampfes. Wann und wo sie erscheinen, steht unter AuraBuffs > Optionen."
L["Add consumables, put them in order, and set each one up."] = "Füge Verbrauchsgüter hinzu, sortiere sie und richte jedes ein."
L["Add Items"] = "Gegenstände einfügen"
L["Add Latency"] = "Latenz einrechnen"
L["Add macros someone shared with you."] = "Füge Makros hinzu, die jemand mit dir geteilt hat."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Füge Befehle hinzu oder entferne sie, schalte jeden ein oder aus oder stelle die Standardbefehle wieder her."
L["Add Slash Command"] = "Slash-Befehl hinzufügen"
L["Add the %s build %s (%d points)?"] = "Den %s-Build %s (%d Punkte) hinzufügen?"
L["Add Themes to RestedXP"] = "Farbthemen zu RestedXP hinzufügen"
L["Add to BiS List"] = "Zur BiS-Liste hinzufügen"
L["Add to Shopping List"] = "Zur Einkaufsliste"
L["Add to the Left Side"] = "Links einfügen"
L["Add to the Right Side"] = "Rechts einfügen"
L["Add your consumables, put them in order, set each one up."] = "Füge deine Verbrauchsgüter hinzu, sortiere sie, richte jedes ein."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Füge den Taschenmakros eigene Zeilen hinzu. Sie bleiben hinter dem Gegenstand, egal was in deinen Taschen ist."
L["Added %d consumable to the Consumable Bar."] = "%d Verbrauchsgut zur Verbrauchsleiste hinzugefügt."
L["Added %d consumables to the Consumable Bar."] = "%d Verbrauchsgüter zur Verbrauchsleiste hinzugefügt."
L["Added %d consumables; %d were already listed or past the %d limit."] = "%d Verbrauchsgüter hinzugefügt; %d waren schon eingetragen oder über der Grenze von %d."
L["Added %d of %d: %s."] = "%d von %d hinzugefügt: %s."
L["Added %d."] = "%d hinzugefügt."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s wurde diesem Charakter hinzugefügt. Ziehe es aus dem Makrofenster des Spiels (/macro) auf eine Leiste."
L["Added %s to your BiS %s as #%d."] = "%s zu deinem BiS für %s als Nr. %d hinzugefügt."
L["Added %s to your BiS %s."] = "%s zu deinem BiS für %s hinzugefügt."
L["Added next to your Library, never over it"] = "Kommt zu deiner Bibliothek dazu, ersetzt sie nie"
L["Added next to your own lists, never over them"] = "Kommt zu deinen eigenen Listen dazu, ersetzt sie nie"
L["Added next to your saved builds"] = "Kommt zu deinen gespeicherten Builds dazu"
L["Adding Items"] = "Gegenstände hinzufügen"
L["Addon Font"] = "Addon-Schriftart"
L["Addon List"] = "Addon-Liste"
L["Addon Memory"] = "Addon-Speicher"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Fügt \"- [1] + Zur Liste\" unter den Reagenzien eines Rezepts hinzu: Die Materialien, die die Funktion Im AH kaufen für so viele Herstellungen kaufen würde, kommen auf eine Einkaufsliste, von überall aus. Im Auktionshaus erscheint die Liste daneben: Preise prüfen schlägt jedes nach und warnt rot, wenn eines deutlich über deinem letzten Scan liegt, dann geht Alle kaufen die Liste Material für Material durch, und jedes wird erst gekauft, wenn du seinen Endpreis bestätigst. Ein Material, das du günstiger aus seinen Teilen herstellen kannst, etwa ein Barren aus Erz, wird stattdessen über seine Teile gekauft."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Ergänzt die Reagenzien des gewählten Rezepts um eine Spalte Taschen, die zeigt, wie viele du von jedem dabeihast."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Ergänzt die Reagenzien des gewählten Rezepts um eine Spalte Bank, die zeigt, wie viele von jedem in deiner Bank liegen."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Fügt dem Pop-up eine Schaltfläche hinzu, die jeden niedrigeren Rang auf deinen Leisten gegen den höchsten Rang tauscht, den du kennst. Bei Tastatur- und Controller-Leisten landet er im selben Feld. Rechtsklicke auf einen Zauber im Pop-up, um seine niedrigeren Ränge zu behalten, fürs Downranking. Rangtausch passiert nur außerhalb des Kampfes."
L["Adds a Land button to come down at the next stop on the way."] = "Fügt eine Schaltfläche Landen hinzu, um an der nächsten Station auf dem Weg zu landen."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Fügt eine Zeile hinzu, die jeden Platz meldet, dessen Verzauberung fehlt oder von denen abweicht, die du mit Aktuelle Verzauberungen erfassen gespeichert hast. Fahre mit der Maus darüber für die Details."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Fügt dem Tooltip eines Manazaubers dessen Heilung oder Schaden pro Mana und pro Sekunde hinzu."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Fügt neben jedem Rezept eine zweite, orangefarbene Zahl hinzu: wie viele du herstellen könntest, nachdem du die Reagenzien gekauft hast, die Händler verkaufen, etwa Schwaches Flussmittel oder Grobes Garn. Die Reagenzien des Rezepts zeigen dann, wie viele du von jedem kaufen musst."
L["Adds how long the visit lasted."] = "Fügt hinzu, wie lange der Besuch gedauert hat."
L["Adds target and focus switching to the meter's title bar."] = "Fügt der Titelleiste der Anzeige einen Wechsel zwischen Ziel und Fokus hinzu."
L["Adds the average experience here."] = "Fügt die durchschnittliche Erfahrung hier hinzu."
L["Adds the coins looted."] = "Fügt das erbeutete Geld hinzu."
L["Adds the consumables in your bags that are not on the bar yet."] = "Fügt die Verbrauchsgüter aus deinen Taschen hinzu, die noch nicht auf der Leiste sind."
L["Adds the deaths."] = "Fügt die Tode hinzu."
L["Adds the experience gained."] = "Fügt die gewonnene Erfahrung hinzu."
L["Adds the materials for one more craft."] = "Fügt die Materialien für eine weitere Herstellung hinzu."
L["Adds the Naowh themes to RestedXP's theme list, in place of the Naowh window."] = "Fügt die Naowh-Farbthemen der Farbthemenliste von RestedXP hinzu, statt des Naowh-Fensters."
L["Adds the Naowh themes to RestedXP's theme list."] = "Fügt die Naowh-Farbthemen der Farbthemenliste von RestedXP hinzu."
L["Adds the reputation gained."] = "Fügt den gewonnenen Ruf hinzu."
L["Adds the visits at this level."] = "Fügt die Besuche auf dieser Stufe hinzu."
L["Adds the visits until you level."] = "Fügt die Besuche bis zum nächsten Stufenaufstieg hinzu."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Rechnet deine Bonusheilung oder deinen Zauberschaden ein; ausgeschaltet zeigt es die Grundwerte des Zaubers."
