L["After each fight longer than 15 seconds, how long you spent neither casting nor on the global cooldown, in chat."] = "Nach jedem Kampf über 15 Sekunden im Chat, wie lange du weder gezaubert hast noch auf der globalen Abklingzeit warst."
L["after the 5% cut"] = "nach 5% Gebühr"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "Nach einem Lehrerbesuch listet ein kleines Fenster die Fähigkeiten auf, die du gerade gelernt hast. Fähigkeiten aus einem Buch oder einer Quest erscheinen kurz nachdem du sie gelernt hast. Ziehe eine aus dem Fenster auf deine Leisten."
