L["Also a grey ! for quests you can still pick up that no longer give experience."] = "Auch ein graues ! für Quests, die du noch annehmen kannst, die aber keine Erfahrung mehr geben."
L["Also a grey star on the map for the rares you have killed."] = "Auch ein grauer Stern auf der Karte für die seltenen Gegner, die du besiegt hast."
L["Also hidden for a few seconds after you dismount, while the pet comes back."] = "Auch einige Sekunden nach dem Absitzen ausgeblendet, während der Begleiter zurückkommt."
L["Also Import"] = "Auch importieren"
L["Also in use on"] = "Auch aktiv auf"
L["Also keeps your last whispers and group chat lines with each player."] = "Behält auch deine letzten Flüsternachrichten und Gruppenchat-Zeilen mit jedem Spieler."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "Öffnet auch die Weltkarte am Wegpunkt, damit du siehst, wo er ist. Nur außerhalb des Kampfes."
L["Also prints the summary when you leave a raid."] = "Schreibt die Zusammenfassung auch, wenn du einen Raid verlässt."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "Erinnert dich auch in Instanzen. Standardmäßig aus: Nur wenige haben Kräuter oder Erz."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "Zeigt den Gewinn jedes Rezepts auch rechts in seiner Zeile der Liste, grün oder rot. Rezepte mit unbekanntem Gewinn zeigen keinen."
L["Also thanks players in your party or raid."] = "Dankt auch Spielern in deiner Gruppe oder deinem Raid."
L["Also used inside dungeons and raids."] = "Gilt auch in Dungeons und Raids."
L["Also warns about rares you have killed before."] = "Warnt auch vor seltenen Gegnern, die du früher schon besiegt hast."
L["Also warns while your pet is set to passive."] = "Warnt auch, solange dein Begleiter auf passiv steht."
L["Also warns while your pet's health is under the threshold, in combat too."] = "Warnt auch, solange die Gesundheit deines Begleiters unter dem Schwellenwert liegt, auch im Kampf."
L["Also worth a look"] = "Auch einen Blick wert"
