L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "Ein Fehler \"Inventar ist voll\" zeigt die Reihe 20 Sekunden lang, auch bei mehr freien Plätzen als die Schwelle oben."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "Ein Twink, der dieses Makro schon hat (nach Name und Text oder nur nach Text), nutzt sein eigenes."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Eine Twinks-Schaltfläche neben dem Reiter zum Senden am Briefkasten listet deine Charaktere auf diesem Realm und dieser Fraktion mit Stufe und Gold auf. Wähle einen, um das Empfängerfeld zu füllen."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Eine Anhängen-Schaltfläche neben dem Reiter zum Senden am Briefkasten: Hänge mit einem Klick alle Handwerkswaren, eine Art Handwerkswaren oder deine ungebundene Ausrüstung an."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "Eine ID, die das Spiel verborgen hält: Ausblenden lässt sie im Tooltip weg, Als verborgen zeigt die Zeile mit Verborgen statt der Zahl."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Ein Gegenstand, der im Auktionshaus mehr wert ist als beim Händler, zählt mit seinem Auktionspreis, aus deinem letzten Preisscan oder TradeSkillMaster."
L["An on-next-swing attack queued on the melee bars."] = "Ein Angriff für den nächsten Swing, vorgemerkt auf den Nahkampfleisten."
