L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "Bei einem Berufslehrer, der eines deiner favorisierten Rezepte lehrt, das du jetzt erlernen kannst (markiere eines mit dem Stern vor seinem Namen oder per Rechtsklick in der Liste), listet ein Fenster neben dem des Lehrers sie mit ihren Kosten auf: Erlernen für eines oder Alle erlernen."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "Füllt bei einem Händler, der sie verkauft, deine Klassenreagenzien und Munition auf die Menge auf, die du dabeihaben willst, und meldet, was es ausgegeben hat. Standardmäßig aus: Es gibt Gold für dich aus."
L["At level %d"] = "Ab Stufe %d"
L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "Nennt beim Einloggen alle deine Charaktere mit Post, die innerhalb von drei Tagen abläuft. Es kennt die Post jedes Charakters vom letzten Mal, als er einen Briefkasten geöffnet hat."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "Im Auktionshaus listet ein Fenster daneben die Muster, Pläne und Handbücher deiner favorisierten Rezepte auf, die du weder erlernt noch gekauft hast, mit ihrem aktuellen Preis. Kauf sucht das günstigste und fragt nach, bevor Annehmen es kauft."
