L["Buys from this merchant, in one click, every checked reagent it sells, for that many crafts, whatever is already in your bags. Set the number with the - and + beside it; uncheck a reagent to leave it out."] = "Kauft mit einem Klick bei diesem Händler jedes markierte Reagenz, das er verkauft, für so viele Herstellungen, egal was schon in deinen Taschen ist. Stell die Anzahl mit - und + daneben ein; entferne den Haken bei einem Reagenz, um es auszulassen."
L["Buys it as it is instead of its parts."] = "Kauft es so, wie es ist, statt seiner Teile."
L["Buys its cheaper parts instead, to make it yourself."] = "Kauft stattdessen seine günstigeren Teile, damit du es selbst herstellst."
L["Buys on the auction house the materials for that many crafts, whatever is already in your bags: every checked reagent that vendors do not sell. Set the number with the - and + beside it; uncheck a reagent to leave it out. Each material asks for the price now and waits for you to confirm."] = "Kauft im Auktionshaus die Materialien für so viele Herstellungen, egal was schon in deinen Taschen ist: jedes markierte Reagenz, das Händler nicht verkaufen. Stell die Anzahl mit - und + daneben ein; entferne den Haken bei einem Reagenz, um es auszulassen. Jedes Material fragt den aktuellen Preis ab und wartet auf deine Bestätigung."
L["Buys what your bags lack of this merchant's reagents for %d crafts, the orange number next to the recipe, so Create All can make them all. Uncheck a reagent to leave it out."] = "Kauft, was deinen Taschen an Reagenzien dieses Händlers für %d Herstellungen fehlt (die orange Zahl neben dem Rezept), damit Alle erstellen alle herstellen kann. Entferne den Haken bei einem Reagenz, um es auszulassen."
