L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "Name oder Symbol jeder Klasse, unter ihrer Schaltfläche oder daneben, wenn die Leiste vertikal ist."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Jeder Dungeon- oder Raidbesuch bei eingeschalteter Instanzstatistik: wie lange du drin warst, das erbeutete Geld und die gewonnene Erfahrung. Gewonnener Ruf steht unter dem Besuch. Kehrst du innerhalb der Stunde zur selben Gruppe zurück, bevor du sie zurücksetzt, läuft der Besuch weiter, und die Zeit draußen zählt nicht. Andere Charaktere bleiben gespeichert und erscheinen hier, wenn Twinks verfolgen an ist. Reparaturen und Verkäufe an Händler zählen nicht. Ältere Besuche fallen am Ende der Liste weg."
L["Each line fades out after %ss."] = "Jede Zeile verblasst nach %ss."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Jedes davon ist ein Accountmakro. Leg es einmal auf eine Leiste, dann hält es sich selbst aktuell: Erbeute einen besseren Trank, beschwöre frisches Essen oder nimm Verbände auf, und das Makro wird so umgeschrieben, dass es das Beste nutzt, was du dabeihast.\n\nDas Spiel lässt Makros im Kampf nicht ändern, deshalb wartet eine Änderung im Kampf, bis er vorbei ist."
L["Each point of the trail in a color of its own."] = "Jeder Punkt der Spur in einer eigenen Farbe."
L["Each slot's item level, in its icon's corner."] = "Die Gegenstandsstufe jedes Platzes, in der Ecke seines Symbols."
L["Each visit, with its time, coins, and experience."] = "Jeder Besuch mit Zeit, Geld und Erfahrung."
