L["Every paladin in your group running Naowh Forever, and the blessing they give each class. Click an icon to change it: your own row always, anyone's while you lead the group or are an assistant. Only what that paladin has learned is offered, and changes reach them straight away."] = "Jeder Paladin in deiner Gruppe mit Naowh Forever und der Segen, den er jeder Klasse gibt. Klicke auf ein Symbol, um ihn zu ändern: deine eigene Zeile immer, die anderer, solange du die Gruppe leitest oder Assistent bist. Angeboten wird nur, was dieser Paladin erlernt hat, und Änderungen erreichen ihn sofort."
