L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Für Paladine eine Schaltfläche pro Klasse in deiner Gruppe. Linksklick segnet das nächste Mitglied dieser Klasse, das ihn braucht, fehlende zuerst, und überspringt Tote und alle außer Reichweite. Rechtsklick auf eine Klasse wählt ihren Segen oder öffnet ihre Spielerliste. Verschiebe sie im HUD-Editor. Die Vorschau ändert sie: Rechtsklick auf eine Klasse für ihren Segen, Klick auf die Aura, um sie zu wählen, Mausrad für Größe und Umschalt-Mausrad für Abstand, ziehe die Lücke hinter der Aura, x blendet eine Schaltfläche aus und + holt sie zurück."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Für Skyborne-Charaktere: Leylinien (Allianz, für Leylinie erschließen) oder Elementarkonvergenzen (Horde, für Himmelssicht) als Pins auf der Weltkarte. Das Spiel markiert sie nicht: Das Addon kennt die, die Spieler gefunden haben, und speichert jede neue, an der du deine Volksfähigkeit wirkst. Andere Völker sehen keine Pins."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Für deine Klasse: importiert dieses Set einmal auf einem neuen Charakter, auf Stufe 1 und noch ohne Erfahrung."
L["For your level"] = "Für deine Stufe"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "%s auf %s vergessen? Er taucht wieder auf, wenn du dich das nächste Mal mit ihm einloggst, während eine Option von Post & Twinks an ist."
