L["Hides the red error text, like \"not ready yet\" and \"out of range\", and the voice line that comes with it."] = "Blendet den roten Fehlertext aus, etwa \"noch nicht bereit\" und \"außer Reichweite\", und die Sprachausgabe dazu."
