L["How close a book has to be before it pings."] = "Wie nah ein Buch sein muss, bevor es pingt."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Wie früh du deinen nächsten Zauber drücken kannst, bevor der aktuelle endet, in Millisekunden. 100 bis 400 passt für die meisten: Niedriger reagiert direkter, höher verzeiht mehr Latenz. Nahkampf etwa dein Ping + 100, Fernkampf etwa dein Ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "Ab wann ein Symbol zu verblassen beginnt, von 0% (sofort) bis 95% (ganz am Ende)."
L["How far below your level gear has to be for Old Common Gear."] = "Wie weit unter deiner Stufe Ausrüstung für Alte einfache Ausrüstung liegen muss."
L["How Group Inspect shows a party and a raid, with sample players."] = "Wie die Gruppenübersicht eine Gruppe und einen Raid zeigt, mit Beispielspielern."
L["How little Camp Benefits time counts as needing a refresh."] = "Ab wie wenig Restzeit der Lagervorteile eine Erneuerung fällig ist."
