L["How long it takes to get there at your speed."] = "Wie lange du mit deinem Tempo bis dorthin brauchst."
L["How long the current fight has run, on screen while you fight. Move it in the HUD Editor."] = "Wie lange der aktuelle Kampf schon läuft, auf dem Bildschirm, während du kämpfst. Verschiebe ihn im HUD-Editor."
L["How long the fight lasted, in chat when it ends."] = "Wie lange der Kampf gedauert hat, im Chat, wenn er endet."
L["How long the next level takes at your current rate."] = "Wie lange die nächste Stufe bei deinem aktuellen Tempo dauert."
L["How long this session has run."] = "Wie lange diese Sitzung schon läuft."
L["How many crafts Add to List adds the materials for."] = "Für wie viele Herstellungen Zur Liste die Materialien hinzufügt."
