L["How many of this material you hand the crafter. Ticking the box fills in all the crafts need; - and + change it by one."] = "Wie viel von diesem Material du dem Handwerker gibst. Der Haken trägt alles ein, was die Herstellungen brauchen; - und + ändern es um eins."
