L["Onboarding"] = "Einrichtung"
L["Once Per Player Every"] = "Einmal pro Spieler alle"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Sobald du das Auktionshaus gescannt hast (Preise scannen), zeigt das gewählte Rezept, was seine Reagenzien im Kauf kosten und wofür sich der Gegenstand verkauft, dazu den Gewinn nach der Auktionshausgebühr von 5%. Jedes Reagenz wird mit seinem günstigsten Preis angesetzt: mit dem Händlerpreis, sobald du es bei einem Händler gesehen hast, sonst mit dem niedrigsten Sofortkaufpreis deines letzten Scans. Wähle ein Reagenz ab, das du schon hast, um es aus den Kosten herauszunehmen, für jedes Rezept, das es nutzt. Zeige mit der Maus auf die Zeilen, um die Aufschlüsselung zu sehen."
L["One addon"] = "Ein Addon"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "Eine Leiste je Waffe, getaktet vom spieleigenen Swing-Ereignis, damit Parierbeschleunigung, zurückgesetzte Swings und Tempo immer stimmen. Verschiebe sie im HUD-Editor."
L["One Fewer"] = "Eins weniger"
L["One item per click: the game needs a click for every disenchant."] = "Ein Gegenstand pro Klick: Das Spiel braucht für jedes Entzaubern einen Klick."
L["One More"] = "Eins mehr"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Eine Zahl für die Ausrüstung eines Charakters, auf der Skala der Gegenstandsstufe: 26.4 bedeutet Ausrüstung im Wert eines Sets epischer Gegenstände der Stufe 26. Deine eigene steht immer in der Charakteransicht der BiS-Liste."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Ein Flüstern pro Zeile, zufällig gewählt; {buff} und {name} werden eingesetzt."
L["Online"] = "Online"
L["Only %d listed right now."] = "Gerade nur %d angeboten."
L["Only buffs a dispel or purge can take off."] = "Nur Buffs, die sich bannen oder reinigen lassen."
L["Only Buffs I Can Cast"] = "Nur Buffs, die ich wirken kann"
