L["Only the gear that beats what you wear: a higher pick on your BiS list, or a higher item level you can wear."] = "Nur Ausrüstung, die besser ist als das, was du trägst: weiter oben auf deiner BiS-Liste oder eine höhere Gegenstandsstufe, die du tragen kannst."
L["Only the group leader can disband the group."] = "Nur der Gruppenanführer kann die Gruppe auflösen."
L["Only the group leader or an assistant can plan every paladin's blessings."] = "Nur der Gruppenleiter oder ein Assistent kann die Segen aller Paladine planen."
L["Only the loot you still need from your BiS list: higher on it than what you wear, and not in your bags or bank."] = "Nur die Beute, die du von deiner BiS-Liste noch brauchst: darauf weiter oben als das, was du trägst, und nicht in deinen Taschen oder deiner Bank."
L["Only the loot your class can use. Off, the rest is listed faded."] = "Nur die Beute, die deine Klasse nutzen kann. Ausgeschaltet wird der Rest verblasst aufgelistet."
L["Only the macros on your kept slots come along."] = "Nur die Makros auf deinen behaltenen Plätzen kommen mit."
L["Only the recipes for the professions you have. Off, every recipe is listed."] = "Nur die Rezepte für deine Berufe. Ausgeschaltet wird jedes Rezept aufgelistet."
L["Only the scores shared over your guild."] = "Nur die über deine Gilde geteilten Punkte."
