L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Öffnet den Berufslink eines anderen Spielers in diesem Fenster, um Herstellungen bei ihm zu bestellen. Wähle ein Rezept, stelle die Zahl der Herstellungen ein, hake die Materialien an, die du mitbringst (oder gib die Anzahl ein), und klicke auf Zum Auftrag. Der Auftrag rechts hat je Herstellung einen Trinkgeldvorschlag, den du ändern kannst; die Anfrage schickt dem Handwerker je Herstellung eine Nachricht mit Menge, deinen Materialien und dem Trinkgeld: im Gruppenchat, wenn er in deiner Gruppe ist, sonst als Flüstern. Preise und Trinkgeld brauchen einen Scan des Auktionshauses."
L["Opens its settings and leaves the HUD Editor."] = "Öffnet seine Optionen und verlässt den HUD-Editor."
L["Opens the Aim Trainer now, out of combat."] = "Öffnet den Zieltrainer jetzt, außerhalb des Kampfes."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Öffnet das AuraBuffs-Fenster, in dem du jeden Gegenstand über seine Gegenstands-ID und Buff-Zauber-ID hinzufügst."
L["Opens the Consumable Bar's settings."] = "Öffnet die Optionen der Verbrauchsleiste."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Öffnet die Kopierkarte für einen Beispielzauber. Markiere die ID oder den Link, dann Strg+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Öffnet die Optionen der Questverfolgung des Dungeonjournals."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Öffnet den HUD-Editor: Klicke ein anderes Element von Naowh Forever an, mit dem sich die Leiste bewegen soll."
L["Opens the Library Books tracker's settings."] = "Öffnet die Optionen des Bibliotheksbücher-Trackers."
L["Opens the planner on its Builds tab."] = "Öffnet den Planer im Reiter Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Öffnet die Questverfolgung draußen in der Welt, für den Dungeon, zu dem deine Quests gehören."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Öffnet die Questverfolgung, wenn du einen Dungeon mit Quests für dich betrittst."
L["Opens the quiz now, or closes it."] = "Öffnet das Quiz jetzt oder schließt es."
L["Opens the Run Timer settings."] = "Öffnet die Optionen des Lauftimers."
L["Opens the Sleeping Bag tracker's settings."] = "Öffnet die Optionen des Schlafsack-Trackers."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Öffnet das Fenster Wertegewichtung: was jeder Wert für deine Spezialisierung wert ist, und deine besten Upgrades danach."
L["Opens the window now, out of combat."] = "Öffnet das Fenster jetzt, außerhalb des Kampfes."
