L["Plays as your target leaves melee range."] = "Ertönt, wenn dein Ziel die Nahkampfreichweite verlässt."
L["Plays Drop Alert with your list's first BiS, as you set it: up for a roll, dropped, then yours."] = "Spielt die Beutemeldung mit dem ersten BiS deiner Liste ab, wie du sie eingestellt hast: wird ausgewürfelt, gedroppt, dann deins."
L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Ertönt jedes Mal einmal, wenn deine Gesundheit unter den Schwellenwert fällt. Verbirgt das Spiel deine Gesundheit im Kampf vor Addons, ertönt der Ton nur außerhalb des Kampfes."
L["Plays once when your threat climbs past the threshold, and again only after it drops back below."] = "Ertönt einmal, wenn deine Bedrohung die Schwelle überschreitet, und erst wieder, nachdem sie darunter gefallen ist."
L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Spielt den Karten-Ping ab und nennt das Buch im Chat, wenn du in Reichweite eines Buchs kommst, das du noch brauchst. Einmal pro Buch, bis du dich entfernst und zurückkommst."
L["Plays the map ping when a book is near."] = "Spielt den Karten-Ping ab, wenn ein Buch in der Nähe ist."
L["Plays the sound again this often while out of range. 0 plays it once."] = "Spielt den Sound in diesem Abstand erneut ab, solange das Ziel außer Reichweite ist. 0 spielt ihn einmal ab."
L["Plays the sound picked here."] = "Spielt den hier gewählten Sound ab."
L["Plays when it is time to refresh the camp."] = "Ertönt, wenn es Zeit ist, das Lager zu erneuern."
L["Plays when the warning comes up, and flashes the game's icon on your taskbar."] = "Ertönt, wenn die Warnung erscheint, und lässt das Spielsymbol in deiner Taskleiste blinken."
