L["Pulsing Targets"] = "Pulsierende Ziele"
L["Put back every setting this page has changed?"] = "Alle Optionen zurücksetzen, die diese Seite geändert hat?"
L["put down what you are holding first."] = "lege zuerst ab, was du gerade hältst."
L["Put every %s weight back to the defaults?"] = "Jedes Gewicht für %s auf den Standard zurücksetzen?"
L["Put every setting back to how it was before the onboarding?"] = "Alle Einstellungen auf den Stand vor der Einrichtung zurücksetzen?"
L["Put every setting in this profile back to its default."] = "Setze jede Einstellung in diesem Profil auf den Standard zurück."
L["Put on in cities and inns, and taken off again when you leave."] = "Wird in Städten und Gasthäusern angelegt und beim Verlassen wieder abgelegt."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Wird beim Reiten angelegt, und das Set, das du anhattest, kommt beim Absitzen zurück."
L["Put the XP Bar colors back to their defaults?"] = "Farben der EP-Leiste auf Standard zurücksetzen?"
L["Put the XP Bar's size and texts back to their defaults?"] = "Größe und Texte der EP-Leiste auf Standard zurücksetzen?"
L["Put this bar back in"] = "Diese Leiste wieder aufnehmen"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Setzt eine Raidmarkierung auf deinen Fokus. Drückst du das Makro erneut beim selben Fokus, wird die Markierung entfernt."
L["Puts back every setting this page has changed, to the value you had before."] = "Setzt alle Optionen, die diese Seite geändert hat, auf deinen vorherigen Wert zurück."
L["Puts back everything changed since the HUD Editor opened."] = "Nimmt alles zurück, was seit dem Öffnen des HUD-Editors geändert wurde."
L["Puts back the last change. Ctrl + Z."] = "Nimmt die letzte Änderung zurück. Strg + Z."
L["Puts both back where the game shows them."] = "Setzt beide dorthin zurück, wo das Spiel sie anzeigt."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Setzt jedes Gewicht dieser Spezialisierung auf den Standard zurück. Fragt vorher."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Setzt Essen, Getränke und Tränke 10 oder mehr Stufen unter dir, mit einer Uhr markiert, an den Anfang."
L["Puts the bar back on the screen."] = "Setzt die Leiste zurück auf den Bildschirm."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Setzt die Schaltflächen der Leiste auf den Standard zurück: Dungeonjournal und Entdeckungen links, BiS-Liste und Ausbildungsplaner rechts."
L["Puts the card back above the middle of the screen, where it starts."] = "Setzt die Warnkarte zurück über die Bildschirmmitte, wo sie anfangs steht."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Setzt den billigsten Gegenstand ans andere Ende der Reihe statt neben ihren Anker."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Legt den billigsten Gegenstand auf deinen Mauszeiger, zum Wegwerfen oder Verkaufen."
L["Puts the count just past the icon's edge."] = "Setzt die Anzahl knapp hinter den Rand des Symbols."
L["Puts the key just past the icon's edge."] = "Setzt die Taste knapp hinter den Rand des Symbols."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Setzt die Materialien für so viele Herstellungen auf deine Einkaufsliste: jedes markierte Reagenz, das Händler nicht verkaufen, egal was in deinen Taschen ist. Entferne den Haken bei einem Reagenz, um es auszulassen. Im Auktionshaus erscheint die Liste daneben, um die Preise zu prüfen und alles zu kaufen."
L["Puts the popup back where it first showed."] = "Setzt das Pop-up dorthin zurück, wo es zuerst erschien."
L["Puts the quiz back where it first opened."] = "Setzt das Quiz dorthin zurück, wo es sich zuerst geöffnet hat."
L["Puts the text just past the icon's edge."] = "Setzt den Text knapp hinter den Rand des Symbols."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Setzt dieses Rezept auf den Auftrag rechts, mit der Anzahl der Herstellungen und den Materialien, die du mitbringst. Änderungen hier nach dem Hinzufügen ändern auch den Auftrag. Bis zu %d Rezepte je Auftrag."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Legt dieses Set an. Im Kampf wird es angelegt, sobald der Kampf endet."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Stellt deine Einstellungen auf eine von Naowhs Einrichtungen um oder führt dich noch einmal durch sie."
