L["Reads every listing on the auction house and keeps the lowest buyout for each item, shown on item tooltips. Blizzard allows one full scan every 15 minutes.\n\n"] = "Liest jedes Angebot im Auktionshaus und merkt sich den niedrigsten Sofortkaufpreis je Gegenstand, angezeigt in den Gegenstands-Tooltips. Blizzard erlaubt einen vollständigen Scan alle 15 Minuten.\n\n"
