L["Reads the gear of the players around you in the background: your target, focus, mouseover and everyone whose nameplate shows, one at a time in inspect range and out of combat."] = "Liest im Hintergrund die Ausrüstung der Spieler um dich herum: dein Ziel, Fokus, den Spieler unter dem Mauszeiger und alle, deren Namensplakette angezeigt wird, einen nach dem anderen in Betrachtungsreichweite und außerhalb des Kampfes."
L["Reads your group members' gear in the background, one at a time while they are in range and out of combat, so their scores are ready before you hover them."] = "Liest im Hintergrund die Ausrüstung deiner Gruppenmitglieder, einen nach dem anderen, solange sie in Reichweite und außerhalb des Kampfes sind, damit ihre Wertungen bereitstehen, bevor du mit der Maus über sie fährst."
