L["Sends the crafter one message per craft: how many you want, the materials you bring and your tip. In party chat, starting with their name, when they are in your party; else as a whisper (also in a raid). The order is emptied once sent."] = "Schickt dem Handwerker eine Nachricht je Herstellung: wie viele du willst, die Materialien, die du mitbringst, und dein Trinkgeld. Im Gruppenchat, beginnend mit seinem Namen, wenn er in deiner Gruppe ist; sonst als Flüstern (auch im Raid). Nach dem Senden wird der Auftrag geleert."
L["Sends the summary to raid chat."] = "Sendet die Zusammenfassung in den Raidchat."
