L["Shown below %d%% health, in combat too."] = "Erscheint unter %d%% Gesundheit, auch im Kampf."
L["Shown For"] = "Anzeigedauer"
L["Shown in a group"] = "In einer Gruppe angezeigt"
L["Shown in combat"] = "Im Kampf angezeigt"
L["Shown in combat."] = "Im Kampf angezeigt."
L["Shown in dungeons and raids."] = "In Dungeons und Raids angezeigt."
L["Shown while you are in a group."] = "Wird angezeigt, solange du in einer Gruppe bist."
L["Shown while you have a bow, gun, crossbow, wand or thrown weapon."] = "Angezeigt, solange du einen Bogen, eine Schusswaffe, eine Armbrust, einen Zauberstab oder eine Wurfwaffe hast."
L["Shown while you have a weapon in your off hand."] = "Angezeigt, solange du eine Waffe in der Schildhand hast."
L["Shown with threat"] = "Bei Bedrohung angezeigt"
L["Shown: click to hide it."] = "Angezeigt: Klicke, um ihn auszublenden."
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Zeigt die Bosse und die Beute eines Dungeons neben der Weltkarte, solange du drin bist."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Zeigt das Symbol eines Heilgegenstands, sobald deine Gesundheit unter den Schwellenwert fällt, auch im Kampf: Das Spiel blendet es selbst ein und aus. Verschiebe es im HUD-Editor."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Zeigt den Tooltip eines Beispielzaubers mit der Zeile, wie deine Optionen sie darstellen."
L["Shows a zone's level range when you hover it on the world map."] = "Zeigt den Stufenbereich eines Gebiets, wenn du auf der Weltkarte mit der Maus darüberfährst."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Zeigt ein Symbol auf dem Bildschirm, solange du Kräutersuche, Mineraliensuche oder Fischsuche kennst, aber keine davon aktiv ist. Klicke darauf, um das Aufspüren zu starten: Linksklick für die erste, Rechtsklick für die zweite, Mittelklick für die dritte. Zeige mit der Maus darauf, um zu sehen, welche welche ist. Im Kampf ausgeblendet. Verschiebe es im HUD-Editor."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Zeigt jeden Schritt zum Schlafsack, mit dem Weg zum nächsten und einem Wegpunkt."
L["Shows every bonus again; click one on the preview to hide it."] = "Zeigt alle Boni wieder an; klicke in der Vorschau auf einen, um ihn auszublenden."
L["Shows how many of each you carry."] = "Zeigt, wie viele du von jedem dabeihast."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Zeigt, ob du vor oder hinter deinen anderen Charakteren liegst, und färbt vergangene Stufen danach."
L["Shows it again a little before its effect runs out."] = "Zeigt ihn kurz vor Ablauf seines Effekts wieder an."
L["Shows only part of the raid."] = "Zeigt nur einen Teil des Raids."
L["Shows or hides the list of every element."] = "Blendet die Liste aller Elemente ein oder aus."
L["Shows the factions earned where you are beside the world map."] = "Zeigt neben der Weltkarte die Fraktionen, bei denen du dort, wo du bist, Ruf bekommst."
L["Shows the key that uses each button."] = "Zeigt die Taste, die jede Schaltfläche auslöst."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Zeigt die Bedrohungsanzeige zehn Sekunden lang mit Beispielleisten an ihrem Platz auf dem Bildschirm. Nur außerhalb des Kampfes."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Zeigt die Debuffs des anderen Tanks neben seiner Gesundheitsleiste, auch im Kampf: Tankbuster-Stapel, Boss-Debuffs und alles, was du bannen kannst."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Zeigt die Teile der Weltkarte, die du noch nicht erkundet hast, abgedunkelt."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "Zeigt die Reihe erst, wenn deine Taschen so voll sind. 0 zeigt sie immer."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Zeigt die noch offenen Schritte zum Schlafsack auf deiner Karte; klicke auf einen für einen Wegpunkt."
L["Shows the warning with its sound, about your target if you can attack it."] = "Zeigt die Warnung mit ihrem Ton, zu deinem Ziel, wenn du es angreifen kannst."
L["Shows this bonus on the bar: %s."] = "Zeigt diesen Bonus auf der Leiste: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Zeigt die Reagenzien dieses Rezepts in deiner Zielverfolgung, mit der Anzahl, die du von jedem hast."
L["Shows this visit's time, coins, and experience."] = "Zeigt Zeit, Geld und Erfahrung dieses Besuchs."
L["Shows up once you take the talent"] = "Erscheint, sobald du das Talent nimmst"
