L["Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full."] = "Nimmt beim Plündern sofort alles, Blizzards Beutefenster bleibt verborgen, sodass du nur den Ticker siehst. Funktioniert mit oder ohne das automatische Plündern des Spiels. Halte beim Plündern Umschalt, um das Fenster zurückzubekommen. Es erscheint auch, wenn etwas nicht genommen werden kann: bei einem Gruppenwurf, einem gesperrten Gegenstand oder zu vollen Taschen."
