L["The boss or place it comes from."] = "Der Boss oder Ort, von dem der Gegenstand stammt."
L["The buffs show while you hover the icon."] = "Die Buffs erscheinen, wenn du mit der Maus über das Symbol fährst."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "Das nächste Talent des Builds kann jetzt nicht genommen werden: Deine Talente sind nicht die des Builds."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "Der Kalender lässt sich mit einem Gamepad nicht über die Obere Leiste öffnen."
L["The card at the end of a round."] = "Die Karte am Ende einer Runde."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Die billigsten Gegenstände in deinen Taschen als Symbolreihe, der billigste zuerst. Klicke mit Strg auf ein Symbol, um es zu zerstören, oder klicke es an, um es bei geöffnetem Händler zu verkaufen. Klicke mit der mittleren Maustaste, um einen Gegenstand zu ignorieren. Verschiebe sie im HUD-Editor."
L["The class's name, or its class icon, which fits however small the buttons are."] = "Der Name der Klasse oder ihr Klassensymbol, das auch auf die kleinsten Schaltflächen passt."
L["The color of the line on the tooltip."] = "Die Farbe der Zeile im Tooltip."
L["The Consumable Bar will ask about those items again."] = "Die Verbrauchsleiste fragt wieder nach diesen Gegenständen."
L["The consumables your reminders watch"] = "Die Verbrauchsgüter, die deine Erinnerungen überwachen"
L["The consumables your reminders watch."] = "Die Verbrauchsgüter, die deine Erinnerungen überwachen."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "Die versteckte Questreihe des Gemütlichen Schlafsacks, Schritt für Schritt."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "Die Kontrolleffekte auf deinem Ziel; welche, wählst du unten in der Karte Kontrolleffekte."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "Die Strg-Klick-Zeile und Klicken zum Verkaufen bei geöffnetem Händler."
L["The cursor left still."] = "Der Mauszeiger steht still."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Die Debuffs auf deinem Ziel, die du unten in der Karte Debuffs wählst, etwa Tödlicher Stoß."
L["The default is %s."] = "Der Standard ist %s."
L["The default is %s. Click to put it back."] = "Standard ist %s. Klicke, um ihn wiederherzustellen."
L["The Disenchant window cannot open in combat."] = "Das Entzauberungsfenster kann im Kampf nicht geöffnet werden."
L["The Dungeon Quest Tracker's window."] = "Das Fenster der Dungeon-Questverfolgung."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Auf wessen Gebiet die aufgelisteten Dungeons liegen. Umkämpfte Dungeons und die Raids werden immer aufgelistet. Auch als Schalter neben der Suche im Journal."
L["The Edit Items window."] = "Das Fenster Gegenstände ändern."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "Der zusätzliche Abstand zwischen deiner Aura samt Zorn der Gerechtigkeit und den Klassenschaltflächen."
L["The fastest way to any waypoint."] = "Der schnellste Weg zu jedem Wegpunkt."
L["The first %d of %d; type more to narrow it down."] = "Die ersten %d von %d; gib mehr ein, um sie einzugrenzen."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "Fragt beim ersten Beitrag eines Spielers dessen Naowh Forever per verstecktem Addon-Flüstern nach seinem Gebiet. Spieler ohne das Addon sehen die Frage nie."
L["The flight time to each destination when you hover it on the flight master's map."] = "Die Flugzeit zu jedem Ziel, wenn du auf der Karte des Flugmeisters mit der Maus darauf zeigst."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "Die Schriftart für Schadens- und Heilungszahlen, über Gegnern und über deinem Charakter. Bei Aus bleibt die Schriftart des Spiels unverändert."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "Die Schriftart für den Rest des Spiels: Menüs, Chat, Tooltips und Namen. Bei Aus bleiben die Schriftarten des Spiels unverändert."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "Die Schriftart für die Fenster und das HUD dieses Addons. Schriftart-Einstellungen einer Funktion nutzen sie, außer sie wählen eine eigene. Wird für diesen Computer gespeichert.|n|nWirkt nach einem /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "Die FPS-/MS-Anzeige und die Online-Zahlen auf den Schaltflächen."
L["The FPS / MS readout stays up."] = "Die FPS-/MS-Anzeige bleibt sichtbar."
L["The game does not name this fight yet: its kills count once the raid opens."] = "Das Spiel benennt diesen Kampf noch nicht: Siege werden gezählt, sobald der Raid öffnet."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "Das Spiel hat noch keinen PvP-Rang für dich. Er erscheint, sobald die Saison begonnen hat."
L["The game has no route for %s, and its quest giver's spot is not known."] = "Das Spiel hat keine Route für %s, und der Standort des Questgebers ist nicht bekannt."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "Das Spiel leitet gerade keine Addon-Nachrichten weiter (in einer Begegnung): Frage danach erneut."
L["The game lists no rank rewards for this season yet."] = "Das Spiel listet für diese Saison noch keine Rangbelohnungen auf."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "Das Spiel wollte das nicht entzaubern (Fertigkeit zu niedrig?). Übersprungen bis zum Neuladen."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Zuerst die eigenen Warntöne des Spiels, dann die des Addons. Jeder ertönt, wenn du ihn auswählst."
L["The gap between the two."] = "Der Abstand zwischen beiden."
L["The gap between two buttons."] = "Der Abstand zwischen zwei Schaltflächen."
L["The Gear Sets window, with every set and what you can do with it."] = "Das Sets-Fenster, mit jedem Set und dem, was du damit tun kannst."
L["The group can be disbanded once the fight is over."] = "Die Gruppe kann aufgelöst werden, sobald der Kampf vorbei ist."
L["The group's paladins and the blessing each gives every class."] = "Die Paladine der Gruppe und der Segen, den jeder von ihnen jeder Klasse gibt."
L["The guild name under a player's name."] = "Der Gildenname unter dem Namen eines Spielers."
L["The highest rank this season"] = "Der höchste Rang dieser Saison"
L["The icon grows and shrinks with it."] = "Das Symbol wächst und schrumpft mit."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "Das Betrachtungsfenster im Stil der BiS-Liste, mit Wertung, Ausrüstungscheck, Talenten und Verlauf des Spielers."
L["The item's cooldown sweeps over its icon."] = "Die Abklingzeit des Gegenstands läuft über sein Symbol."
L["The item's quality"] = "Qualität"
L["The item, your star and what happened, on screen for a while."] = "Der Gegenstand, dein Stern und was passiert ist, eine Weile auf dem Bildschirm."
L["The items the Buffs & Consumables reminders watch."] = "Die Gegenstände, die von den Erinnerungen unter Buffs & Verbrauchsgüter überwacht werden."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "Das Journal neben der Weltkarte: Bosse und Beute in Dungeons, Fraktionen außerhalb."
L["The Journal's own window."] = "Das eigene Fenster des Journals."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "Die Taste, die Quests annehmen, Quests abgeben, Quests bei NSCs wählen und das Teilen ändert."
L["The key that changes Auto Gossip for that NPC."] = "Die Taste, die Auto-Gespräch für diesen NSC ändert."
L["The key that opens the BiS List."] = "Die Taste zum Öffnen der BiS-Liste."
L["The key that opens the Journal."] = "Die Taste, die das Journal öffnet."
L["The key that opens the Quest List window."] = "Die Taste, die das Fenster der Questliste öffnet."
L["The last %ds, scrolling %s%s"] = "Die letzten %ds, Richtung %s%s"
L["The last fight's time stays on screen until the next one starts."] = "Die Zeit des letzten Kampfes bleibt auf dem Bildschirm, bis der nächste beginnt."
L["The last part of each melee swing, shaded."] = "Der letzte Teil jedes Nahkampfschwungs, schattiert."
L["the last profile cannot be deleted"] = "das letzte Profil kann nicht gelöscht werden"
L["The last profile cannot be deleted."] = "Das letzte Profil kann nicht gelöscht werden."
L["The latest %d kills. First counted: %s."] = "Die letzten %d Siege. Zuerst gezählt: %s."
L["The latest %d. First counted: %s."] = "Die letzten %d. Zuerst gezählt: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "Das Gebiet des Anführers bei jedem Eintrag der Gruppensuche und das Gebiet jedes Mitglieds, wenn du mit der Maus darüberfährst."
L["The level you are on as it runs, then completed levels, newest first."] = "Die aktuelle Stufe, während sie läuft, dann abgeschlossene Stufen, die neueste zuerst."
L["The line round the bar."] = "Die Linie um die Leiste."
L["The list this character uses."] = "Die Liste, die dieser Charakter nutzt."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "Die längste Dauer, bei der ein Buff noch angezeigt wird; längere wie Arkane Intelligenz bleiben verborgen."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "Die Makros, die das Addon außerhalb des Kampfes für dich schreibt und aktuell hält. Schalte hier eines ein oder ziehe es aus Smart-Makros in Naowh's Forge auf deine Leisten."
L["The Man. The King."] = "Der Mann. Der König."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "Das Fenster der Karte, das Journal neben der Weltkarte und Bossbeute am Mauszeiger."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "Die Markierungen im Charakterfenster des Spiels, so wie es aussieht (oder in dem von EllesmereUI), ohne das Naowh-Charakterfenster. Ist es an, haben seine Plätze sie bereits."
L["The Middle-click line."] = "Die Mittelklick-Zeile."
L["The most recent completed levels."] = "Die zuletzt abgeschlossenen Stufen."
L["the name is empty"] = "der Name ist leer"
L["The name on it, and the community it is made for."] = "Der Name darauf und die Community, für die es gemacht ist."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "Die Schaltfläche von Naowh Forever an der Minikarte. Der Eintrag im Addon-Fach und /naowh öffnen dieses Fenster so oder so."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "Das Naowh-Forever-N neben dem Namen von Naowh, den Entwicklern, den Moderatoren und unseren legendären und epischen Unterstützern im Chat."
L["The newest line stays at the anchor; older lines stack in this direction."] = "Die neueste Zeile bleibt am Anker; ältere Zeilen stapeln sich in diese Richtung."
L["The next one frees in "] = "Die nächste wird frei in "
L["the next rank of %s (cap %d)"] = "die nächste Rangstufe von %s (max. %d)"
L["The number on each icon counts your bank as well as your bags."] = "Die Zahl auf jedem Symbol zählt neben deinen Taschen auch deine Bank."
L["The order the points are taken in"] = "Die Reihenfolge, in der die Punkte gesetzt werden"
L["the pattern"] = "das Muster"
L["The people and projects behind Naowh Forever."] = "Die Menschen und Projekte hinter Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "Beute und Fähigkeiten des gewählten Bosses, unter der Karte."
L["The planner's own window, and a mini bar to leave up while you level."] = "Das eigene Fenster des Planers und eine Minileiste, die du beim Aufsteigen offen lassen kannst."
L["The player list opens after combat."] = "Die Spielerliste öffnet sich nach dem Kampf."
L["The player's guild rank beside their guild name."] = "Der Gildenrang des Spielers neben seinem Gildennamen."
L["The point of the bar that attaches."] = "Der Punkt der Leiste, der gebunden wird."
L["The point of the frame it attaches to."] = "Der Punkt des Fensters, an den sie gebunden wird."
L["The purchase failed."] = "Der Kauf ist fehlgeschlagen."
L["The purchase failed; the price may have changed."] = "Der Kauf ist fehlgeschlagen; der Preis hat sich womöglich geändert."
L["The purchase failed; the price may have changed.|r"] = "Der Kauf ist fehlgeschlagen; der Preis hat sich vielleicht geändert.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "Die Questverfolgung und das Teilen von Dungeonquests mit deiner Gruppe."
L["The quests that reward a pick you do not have yet."] = "Die Quests, die einen Favoriten als Belohnung geben, den du noch nicht hast."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "Das Quiz öffnet sich, wenn du dich an ein Lagerfeuer setzt, und schließt sich, wenn du aufstehst."
L["The raid marker Mark Focus puts on your focus."] = "Die Raidmarkierung, die beim Markieren auf deinen Fokus gesetzt wird."
L["the rank before"] = "den Rang davor"
L["The ready ring shows with GCD Sweep on."] = "Der Bereit-Ring erscheint, wenn GCD-Umlauf an ist."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Die Reagenzien, die deine bekannten Zauber brauchen, etwa Arkanes Pulver, Kerzen, Samen, Symbole der Könige und Blitzstrahlpulver, passend zum höchsten Rang, den du kennst."
L["The red time left blinks, to catch your eye."] = "Die rote Restzeit blinkt, damit sie dir auffällt."
L["The same required-level filter applies to every stack, not each item separately."] = "Derselbe Filter für die benötigte Stufe gilt für jeden Stapel, nicht für jeden Gegenstand einzeln."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Dieselben Sets wie im Charakterfenster: Anlegen, speichern, umbenennen oder löschen kannst du sie im Sets-Fenster."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "Dasselbe mit einem Großen Segen für eine Klasse mit gemeinsamem Segen, solange du Symbole der Könige dabeihast."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Die Restsekunden, ab denen die Zeit rot wird; gelb wird sie beim Doppelten."
L["The serializer libraries are missing from this build."] = "Die Serialisierungs-Bibliotheken fehlen in dieser Version."
L["The shape of Naowh's arrow."] = "Die Form von Naowhs Pfeil."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "Der Anteil am Verkaufswert der Gegenstände, den der Trinkgeldvorschlag zusätzlich zur Erstattung der eigenen Materialien des Handwerkers aufschlägt. Mindestens 1s, außer bei 0."
L["The shortest time between two thanks to the same player."] = "Die kürzeste Zeit zwischen zwei Danksagungen an denselben Spieler."
L["The Slot"] = "Der Platz"
L["The slot it is for."] = "Der Platz des Gegenstands."
L["The slots and stats only"] = "Nur die Plätze und Werte"
L["The space between Naowh's arrow and the text under it."] = "Der Abstand zwischen Naowhs Pfeil und dem Text darunter."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "Die Spezialisierung, für die deine Ausrüstung gewichtet wird. Automatisch folgt deinen Talenten: der Baum mit den meisten Punkten (Wilder Kampf eines Druiden wird für Schaden gewichtet; wähle Feral Tank für einen Bären)."
L["The spot ahead of you, 312 yards away."] = "Die Stelle vor dir, 312 Meter entfernt."
L["The spot off to your right."] = "Die Stelle rechts von dir."
L["The stat weights each spec starts with."] = "Die Wertegewichtung, mit der jede Spezialisierung startet."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "Der Text bei Verstohlenheit, solange du verstohlen bist, ebenso die Erinnerung, wenn du es nicht bist."
L["The step and distance text under RestedXP's waypoint arrow."] = "Der Text mit Schritt und Entfernung unter dem Wegpunktpfeil von RestedXP."
L["The string is damaged: copy it again in full."] = "Der String ist beschädigt: Kopiere ihn noch einmal vollständig."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "Das vorgeschlagene Trinkgeld erstattet die Materialien des Handwerkers plus %d%% des Verkaufswerts der Gegenstände (bei einem Rezept ohne Gegenstand: aller Materialien), gerundet, mindestens 1s. Ein eigenes Trinkgeld setzt du in der Auftragsliste rechts. Den Anteil änderst du in den Berufe-Optionen."
L["The swing timer needs WoW: Forever's own swing event."] = "Der Swing-Timer braucht das eigene Swing-Ereignis von WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "Die Kennzeichnung in der Klassenfarbe des Sprechers. Ausgeschaltet ist sie grau."
L["the talent above it"] = "das Talent darüber"
L["The talent builds you saved in the Training Planner."] = "Die Talentbuilds, die du im Ausbildungsplaner gespeichert hast."
L["The Team"] = "Das Team"
L["The text in the theme's accent color instead of gold."] = "Der Text in der Akzentfarbe des Farbthemas statt in Gold."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "Das Farbthema, das RestedXP nutzt: sein eigenes oder eines der Naowh-Farbthemen."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "Die Uhrzeit zwischen den beiden Seiten. Klicke darauf für den Kalender (nicht mit einem Gamepad)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "Die Restzeit wird gelb und kurz vor dem Ende rot, damit du siehst, wann Kontrolleffekte gleich brechen."
L["The time left, turning yellow, then red, as the camp runs down."] = "Die Restzeit, die erst gelb, dann rot wird, während das Lager abläuft."
L["The tint on every button's icon: Naowh's own and any addon's."] = "Die Tönung der Symbole aller Schaltflächen: Naowhs eigene und die anderer Addons."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "Die Hilfe des Trainingsplaners beim Aufsteigen: eine Meldung, wenn du eine Stufe aufsteigst und Zauber zu lernen hast, und ein Fenster neben deinem Klassenlehrer."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "Das Einheitenfenster, an das die Leiste gebunden ist, oder UIParent für den Bildschirm."
L["The weights"] = "Die Gewichtung"
L["The weights for %s."] = "Die Gewichtung für %s."
L["The window's border fades with it."] = "Der Rand des Fensters verblasst mit."
L["The word itself."] = "Das Wort selbst."
L["The XP of completed quests, and their text."] = "Die EP erledigter Quests und ihr Text."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "Die EP noch laufender Quests als blasser Abschnitt nach den erledigten."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "Die EP noch offener Quests. Standardmäßig die Farbe erledigter Quests, verblasst."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "Das Gebiet aller, die in einem Chatkanal, im Gildenchat oder per Flüstern schreiben, vor ihrer Nachricht. Das Spiel verrät nie, wo ein Fremder ist, daher wird ein Spieler gekennzeichnet, sobald er in der Gruppensuche, deiner Gilde, deiner Freundesliste oder deiner Gruppe ist, in einem /who auftauchte oder aus seinem eigenen Naowh Forever geantwortet hat. Seine erste Nachricht kann ohne Kennzeichnung durchkommen."
L["Their BiS"] = "Ihr BiS"
L["THEIR GEAR"] = "AUSRÜSTUNG"
L["Their gear, talents and history"] = "Ausrüstung, Talente und Verlauf des Spielers"
L["their materials + %d%%"] = "Material des Herstellers + %d%%"
L["Their materials:"] = "Material des Herstellers:"
L["Their Naowh Score at the top of the panel, with yours under it."] = "Der Naowh Score des Spielers oben im Fenster, deiner darunter."
L["Their supporter badge in the window's corner, if they have one."] = "Das Unterstützerabzeichen des Spielers in der Fensterecke, falls er eins hat."
L["Thelsamar"] = "Thelsamar"
L["Them"] = "Spieler"
L["them all."] = "zu beherrschen."
L["Theme"] = "Farbthema"
L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Farbthema-Vorlagen für die Fenster und HUD-Elemente des Addons, dazu die Option Eigene für selbst gewählte Farben. Wird Text schwer lesbar, wähle Naowh (Standard). Wird für diesen Computer gespeichert.|n|nWirkt nach einem /reload."
L["then"] = "dann"
L["then "] = "dann "
L["There are no consumables to export yet."] = "Es gibt noch keine Verbrauchsgüter zum Exportieren."
L["There is already a bar set called %s."] = "Es gibt schon ein Leistenset namens %s."
L["There is already a layout named %s."] = "Es gibt bereits ein Layout namens %s."
L["There is no item with that ID."] = "Es gibt keinen Gegenstand mit dieser ID."
L["There is nothing to export yet."] = "Es gibt noch nichts zu exportieren."
L["They keep themselves up to date from your bags and gear"] = "Sie halten sich anhand deiner Taschen und Ausrüstung selbst aktuell"
L["They wait in your mailbox.|r"] = "Sie warten in deinem Briefkasten.|r"
L["Thick Circle"] = "Dicker Kreis"
L["Thick Outline"] = "Dicker Umriss"
L["Thickness"] = "Dicke"
L["Thin Circle"] = "Dünner Kreis"
L["This Character"] = "Dieser Charakter"
L["This character's latest kills and loot."] = "Die neuesten Siege und Beute dieses Charakters."
L["This character's macros"] = "Makros dieses Charakters"
L["This client has no swing event"] = "Dieser Client hat kein Swing-Ereignis"
L["THIS HOUR"] = "DIESE STUNDE"
L["This Hour"] = "Diese Stunde"
L["This is a BiS list. It is added next to your own lists."] = "Das ist eine BiS-Liste. Sie wird neben deinen eigenen Listen hinzugefügt."
L["This is a new adventure for all of us. Naowh Forever is crafted by a small, dedicated team with a lot of passion, and we hope you enjoy every bit of it."] = "Das ist für uns alle ein neues Abenteuer. Naowh Forever wird von einem kleinen, engagierten Team mit viel Leidenschaft gebaut, und wir hoffen, dass dir jedes Stück davon gefällt."
L["This is a talent build. It is added to your builds in the Training Planner."] = "Das ist ein Talentbuild. Er wird deinen Builds im Ausbildungsplaner hinzugefügt."
L["This is not a Naowh Forever profile string."] = "Das ist kein Profil-String von Naowh Forever."
L["This item's own settings on the bar."] = "Die eigenen Optionen dieses Gegenstands auf der Leiste."
L["This Level:|r "] = "Diese Stufe:|r "
L["This profile is too big to share."] = "Dieses Profil ist zu groß zum Teilen."
L["This rare dropped it for you."] = "Du hast es von diesem seltenen Gegner erbeutet."
L["This set holds %s."] = "Dieses Set enthält %s."
L["This string is from a newer Naowh Forever: update first."] = "Dieser String stammt aus einer neueren Version von Naowh Forever: Aktualisiere zuerst."
L["This string is too big."] = "Dieser String ist zu groß."
L["This week you can reach rank %d of %d; the faint ranks open in the weeks to come."] = "Diese Woche kannst du Rang %d von %d erreichen; die blassen Ränge öffnen sich in den kommenden Wochen."
