L["What the whole stack sells for at a vendor, and each item's price."] = "Was der ganze Stapel beim Händler einbringt, und der Preis pro Stück."
L["What to train at each level, and its cost."] = "Was du auf jeder Stufe lernst und was es kostet."
L["What you can train now and what each level brings."] = "Was du jetzt lernen kannst und was jede Stufe bringt."
L["What you can train now, what each level brings and what it costs."] = "Was du jetzt lernen kannst, was jede Stufe bringt und was es kostet."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "Was du dem Handwerker für diese Herstellung zahlst, mit dem Flüstern geschickt. Vorbelegt mit dem vorgeschlagenen Trinkgeld; gib dein eigenes als 2g 50s, 75s oder 2.5 (Gold) ein. Leere das Feld, um zum Vorschlag zurückzukehren."
L["What you wear that takes a better enchant for your level."] = "Getragene Ausrüstung, die eine bessere Verzauberung für deine Stufe bekommen kann."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "Was dein Ziel im Kampf tut: seine kurzen Buffs und die Kontrolleffekte auf ihm."
L["Wheel"] = "Mausrad"
L["Wheel on the rows"] = "Mausrad über den Zeilen"
L["Wheel: size. Right-click for more."] = "Mausrad: Größe. Rechtsklick für mehr."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Mausrad: Textgröße. Klicke eine Zeile an, um sie auszublenden. Rechtsklick für mehr."
L["When"] = "Wann"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Reicht die Fertigkeit eines Berufs für seinen nächsten Rang (Geselle, Experte, Fachmann), zeigt ein Banner unter der Fertigkeitsleiste und auf seiner Karte in der Übersicht, was es dafür braucht und wer ihn lehrt: der nächstgelegene Lehrer, Buchhändler oder Questgeber. Klicke auf Wegpunkt, um ihn auf deiner Karte zu markieren. Beim Erreichen steht das auch einmal im Chat; /naowh profrank wiederholt das."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Wenn ein Gegenstand deiner Liste ausgewürfelt wird oder im Beutefenster liegt, und erneut, wenn er dir gehört. Verschiebe die Bildschirmmeldung im HUD-Editor."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Bietet ein NSC mehreres an, geht es direkt zu einer abgeschlossenen Quest zum Abgeben oder zur ersten angebotenen Quest. Arbeitet mit den beiden Optionen darüber zusammen."
L["When it is up for a roll or drops."] = "Wenn darum gewürfelt wird oder es droppt."
L["When it is yours."] = "Wenn es dir gehört."
L["When You Leave"] = "Beim Verlassen"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Wenn du eine Stufe aufsteigst und neue Zauber zu lernen hast, zeigt eine Meldung, wie viele es sind und was sie kosten, mit Schaltflächen, um den Planer zu öffnen und einen Wegpunkt zu deinem nächsten Lehrer zu setzen. Verschiebe sie im HUD-Editor."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "Beim Ausloggen wird das zuletzt gesicherte Set dieses Charakters mit deinen aktuellen Leisten, Makros und Tastenbelegungen erneut gesichert."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Wenn du eine Stadt oder ein Gasthaus erreichst, eine blinkende Liste in der Bildschirmmitte mit allem, was dir fehlt. Sie bleibt, bis du alles hast oder gehst. Verschiebe sie im HUD-Editor."
L["When You Reset"] = "Beim Zurücksetzen"
L["Where"] = "Wohin"
L["Where %s starts is not known."] = "Wo %s beginnt, ist nicht bekannt."
L["Where do you want to start?"] = "Womit möchtest du starten?"
L["Where it comes from is not recorded yet; try the Auction House."] = "Woher es kommt, ist noch nicht erfasst; versuche es im Auktionshaus."
L["Where It Drops"] = "Herkunft"
L["Where on the frame the bar sits."] = "Wo am Fenster die Leiste sitzt."
L["Where to get them"] = "Wo du sie bekommst"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Wo dein Abstand zur Aggroschwelle und die Zahl der Einträge stehen: unter den Leisten oder zwischen Titelleiste und Leisten."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Wo dein Stern sitzt: an der Ecke des Symbols, vor dem Namen oder ausgeblendet."
L["Where? on Whispers"] = "Wo? beim Flüstern"
L["Whether a healthstone or a potion comes first."] = "Ob ein Gesundheitsstein oder ein Trank zuerst kommt."
L["Whether a new mark counts on every character or only this one."] = "Ob eine neue Markierung für alle Charaktere gilt oder nur für diesen."
L["Whether NF Food leaves drinks to NF Drink."] = "Ob NF Food Getränke NF Drink überlässt."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Welche Kontrolleffekte angezeigt werden, nach Fähigkeit: alle Ränge und derselbe Zauber von Gegenständen und Kreaturen."
L["Which debuffs show beside crowd control: off until you light them."] = "Welche Debuffs neben Kontrolleffekten angezeigt werden: aus, bis du sie aufhellst."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Welche Gilden- und Titelzeilen bei Spielernamen erscheinen, vom Spiel selbst gespeichert."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Welche Arten von Verbrauchsgütern Taschen durchsuchen hinzufügt und wonach Nachfragen fragt."
L["Which mana spells get the line."] = "Welche Manazauber die Zeile bekommen."
L["Which modules do you want?"] = "Welche Module möchtest du?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Welche deiner Favoriten melden: nur dein BiS, deine Top 2 oder jeder Favorit deiner Liste."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "Was das Makro zuerst benutzt, wenn du beides dabeihast: einen Gesundheitsstein oder einen Heiltrank."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Ist ein Händler geöffnet, kauft eine Schaltfläche Kauf unter den Reagenzien des gewählten Rezepts mit einem Klick bei ihm jedes angehakte Reagenz, das er verkauft, etwa Grobes Garn oder Schwaches Flussmittel, für so viele Herstellungen, wie du daneben einstellst. Die Gesamtkosten stehen neben der Schaltfläche; zeige mit der Maus auf Kauf für die einzelnen Reagenzien."
L["While flying"] = "Im Flug"
L["While flying and at the campfire"] = "Im Flug und am Lagerfeuer"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Solange Heldenhafter Stoß, Spalten, Zermalmen oder Raptorstoß vorgemerkt ist, übernehmen die Nahkampfleisten dessen Farbe und Namen."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Ist das Auktionshaus geöffnet, kauft eine Schaltfläche Kauf unter den Reagenzien des gewählten Rezepts die Materialien für so viele Herstellungen, wie du daneben einstellst: jedes angehakte Reagenz, das Händler nicht verkaufen. Jedes zeigt zuerst seinen Preis und wird erst gekauft, wenn du auf Bestätigen klickst."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Ist das Auktionshaus geöffnet, sucht eine Schaltfläche AH-Suche neben dem Namen des gewählten Rezepts dort nach dem Gegenstand, den das Rezept herstellt. Nicht erlernte Rezepte bekommen auch die Schaltfläche Rezept, für das Muster, die Pläne oder das Handbuch, das es lehrt. Rezepte, die keinen Gegenstand herstellen, etwa Verzauberungen, bekommen keine AH-Suche."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Ist das Auktionshaus geöffnet, klicke mit Shift auf ein Rezept oder ein Reagenz, um im Auktionshaus nach dem Gegenstand zu suchen: dem, was das Rezept herstellt, oder dem Reagenz. Während du im Chat schreibst, verlinkt Shift-Klick es weiterhin."
L["While the mouse is away, with Show On Mouseover on."] = "Solange die Maus weg ist und Bei Mouseover anzeigen an ist."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "Teilt in einer Gruppe jede Quest, die du von einem NSC annimmst, mit den anderen, wenn sie teilbar ist. Eine Quest, die jemand mit dir geteilt hat, wird nicht erneut geteilt. Hältst du beim Annehmen die Zusatztaste, behältst du sie für dich."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Solange du Bücher dabeihast, ein Pin bei dem, der sie annimmt: deinem Bibliothekar oder dem Magierlehrer."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Markiert beim Zaubern, wo der Zauber auf der Waffenhand-Leiste endet. Die Marke wird rot, wenn der Zauber noch läuft, sobald der Swing fällig ist."
