L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "Flüstert einen Dank, wenn dir ein Spieler in der offenen Welt einen Klassenbuff gibt; schalte freundliche Namensplaketten ein, damit das Spiel ihn nennen kann."
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "Weiß: genau, aus ihrem Naowh Forever. Grau: aus ihrer Ausrüstung zusammengezählt."
L["Who the cast is aimed at, in their class color."] = "Auf wen der Zauber zielt, in seiner Klassenfarbe."
L["Whoever holds aggro in one color."] = "Wer die Aggro hat, in einer Farbe."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "Wessen Rangliste die Auswahl zeigt. Jede Spezialisierung hat auf einer Liste ihre eigenen Favoriten."
L["Wide kite"] = "Breiter Drachen"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "Verbreitert die Fenster für Swing und Automatischen Schuss um deine Weltlatenz, damit sie zeigen, wann du drücken musst, und nicht, wann der Server handelt."
