L["Your cast will still be going as the swing comes due."] = "Dein Zauber läuft noch, wenn der Swing fällig ist."
L["Your casts and channels swept around the ring too."] = "Auch deine Zauber und kanalisierten Zauber laufen um den Ring."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Dein Charakterfenster (C) im Stil der BiS-Liste: jeder Platz mit seinen Markierungen, deine Werte für deine Spezialisierung und dein Naowh Score unter deiner Stufe. Das Spiel behält das Fenster und alles, was es tut. Mit EllesmereUI schaltet dies beim Einschalten dessen Charakterfenster aus und beim Ausschalten wieder ein, nach einem Neuladen."
L["Your Characters"] = "Deine Charaktere"
L["Your characters at level %d"] = "Deine Charaktere auf Stufe %d"
L["Your characters at level %d (%s)"] = "Deine Charaktere auf Stufe %d (%s)"
L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "Deine Charaktere auf diesem Realm und dieser Fraktion, accountweit gemerkt: ihr Besitz in Gegenstands-Tooltips und Hilfe am Briefkasten."
L["Your Chat"] = "Dein Chat"
L["Your chat only"] = "Nur in deinem Chat"
L["Your class macros and the Macros settings"] = "Deine Klassenmakros und die Optionen von Makros"
L["Your class macros and the Macros settings."] = "Deine Klassenmakros und die Optionen von Makros."
L["Your class's BiS lists"] = "BiS-Listen deiner Klasse"
L["Your class's trainers only."] = "Nur die Lehrer deiner Klasse."
L["Your Color"] = "Deine Farbe"
L["Your consumables on a bar you can click."] = "Deine Verbrauchsgüter auf einer Leiste zum Anklicken."
L["Your Corpse"] = "Deine Leiche"
L["your debuffs"] = "deine Debuffs"
L["Your equipment sets, the same ones the character sheet keeps."] = "Deine Ausrüstungssets, dieselben, die das Charakterfenster verwaltet."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Deine Erfahrung pro Stunde auf einer kleinen Karte, mit Zeit bis zum Aufstieg, Spielzeit, Sitzungsdauer und den letzten Stufenzeiten. Auf Höchststufe ausgeblendet. Fahre mit der Maus darüber für Start, Pause und Zurücksetzen (auch /naowh xp start, pause oder reset). Verschiebe sie im HUD-Editor."
L["Your experience. Its left end is a darker shade."] = "Deine Erfahrung. Ihr linkes Ende ist dunkler getönt."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Dein Flug auf einer Karte: Restzeit, die Stationen auf einer Strecke und die nächste Station."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Die Zauber deines Fokusziels auf einer eigenen Leiste, gefärbt danach, ob deine Unterbrechung bereit ist, mit einer Markierung, wo ihre Abklingzeit endet, und einem Schild bei Zaubern, die du nicht unterbrechen kannst. Als Unterbrechung gilt die erste, die du von diesen kennst: Zuschlagen, Schildhieb, Tritt, Gegenzauber, Erdschock, Stille und Wilde Attacke. Verschiebe sie im HUD-Editor."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "Der Name deines Fokus in Klassenfarbe, mit seinem Klassensymbol über der Anzeige."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Dein Fokus, gesetzt mit NF Focus: Seine Timer laufen weiter, während du jemand anderen bekämpfst."
L["Your game macros, not the Smart Macros, as one string to share."] = "Deine Spielmakros, nicht die Smart-Makros, als ein String zum Teilen."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Deine globale Abklingzeit als Umlauf um den Ring und ein Bereit-Ring, sobald sie vorbei ist."
L["YOUR GOLD"] = "DEIN GOLD"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "Deine Gruppe in Reichweite: wem ein Segen fehlt, bei wem er ausläuft und wer nur seinen eigenen braucht."
L["Your group on a boss you are tanking."] = "Deine Gruppe an einem Boss, den du tankst."
L["Your group's bars, with sample members."] = "Die Leisten deiner Gruppe, mit Beispielmitgliedern."
L["Your group's gear, talents and Naowh Score."] = "Ausrüstung, Talente und Naowh Score deiner Gruppe."
L["Your group's healers and their mana, lowest first."] = "Die Heiler deiner Gruppe und ihr Mana, niedrigstes zuerst."
L["Your group's Naowh Score, gear, talents and stats."] = "Naowh Score, Ausrüstung, Talente und Werte deiner Gruppe."
L["Your group's threat on your target."] = "Die Bedrohung deiner Gruppe auf deinem Ziel."
L["Your healers' mana, with sample healers."] = "Das Mana deiner Heiler, mit Beispielheilern."
L["Your health under the threshold, with a healing item in your bags."] = "Deine Gesundheit unter dem Schwellenwert, mit einem Heilgegenstand in deinen Taschen."
L["Your health under the threshold, with nothing to drink or eat."] = "Deine Gesundheit unter dem Schwellenwert, ohne etwas zu trinken oder zu essen."
L["Your keys stay as they are."] = "Deine Tasten bleiben, wie sie sind."
L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Deine Stufe, Erfahrung und Prozent auf einer Leiste, mit den EP erledigter Quests und dem Erholungsbonus über die Füllung hinaus. Ersetzt Blizzards Erfahrungsleiste, solange sie an ist. Verschiebe sie im HUD-Editor. Klicke mit Strg + rechter Maustaste auf die Leiste, um Sitzungszeit und EP/Stunde zurückzusetzen."
L["Your List"] = "Deine Liste"
