L["Your recent casts as icons scrolling away from a point, with a bar underneath while you were casting or on the global cooldown. Gaps in the bar are time spent doing nothing. Move it in the HUD Editor."] = "Deine letzten Zauber als Symbole, die von einem Punkt weglaufen, mit einer Leiste darunter, solange du gezaubert hast oder auf der globalen Abklingzeit warst. Lücken in der Leiste sind Zeit, in der du nichts getan hast. Verschiebe sie im HUD-Editor."
