L["Your characters' code, to add them to your badge on naowh.gg."] = "Der Code deiner Charaktere, um sie auf naowh.gg deinem Abzeichen hinzuzufügen."
L["Your Badge"] = "Dein Abzeichen"
L["Your badge on this character, and whether it matched the BattleTag saved on naowh.gg."] = "Dein Abzeichen auf diesem Charakter und ob es zum auf naowh.gg gespeicherten BattleTag passt."
L["Claim"] = "Einlösen"
L["Paste the claim code from naowh.gg, if the Naowh Forever app doesn't do it for you."] = "Füge den Code von naowh.gg ein, falls die App von Naowh Forever das nicht für dich erledigt."
L["Paste your claim code from naowh.gg"] = "Füge deinen Code von naowh.gg ein"
L["No badge on this character"] = "Kein Abzeichen auf diesem Charakter"
L["%s, your claim matches naowh.gg"] = "%s, dein Code passt zu naowh.gg"
L["%s, checking your claim"] = "%s, dein Code wird geprüft"
L["%s, not claimed on this character yet"] = "%s, auf diesem Charakter noch nicht eingelöst"
L["%s, off: the claim or BattleTag does not match naowh.gg"] = "%s, aus: Code oder BattleTag passt nicht zu naowh.gg"
L["That is not a claim code: it looks like K7P2-9XQM, from your naowh.gg account."] = "Das ist kein gültiger Code: Er sieht aus wie K7P2-9XQM und steht in deinem Konto auf naowh.gg."
L["Your Naowh Forever badge is claimed on this character."] = "Dein Abzeichen von Naowh Forever ist auf diesem Charakter eingelöst."
L["That claim is not this character's, or the BattleTag saved on naowh.gg is not yours."] = "Dieser Code gehört nicht zu diesem Charakter, oder der auf naowh.gg gespeicherte BattleTag ist nicht deiner."
L["Claim saved: your badge shows once this character is on the badge list, with the next Naowh Forever update."] = "Code gespeichert: Dein Abzeichen erscheint, sobald dieser Charakter mit dem nächsten Update von Naowh Forever auf der Abzeichenliste steht."
L["Your Naowh Forever badge needs claiming on this character: the Naowh Forever app does it for you, or type /nf badges claim with the code from your naowh.gg account."] = "Dein Abzeichen von Naowh Forever muss auf diesem Charakter noch eingelöst werden: Die App von Naowh Forever erledigt das für dich, oder gib /nf badges claim mit dem Code aus deinem Konto auf naowh.gg ein."
L["Your Naowh Forever badge is off on this character: its claim, or the BattleTag saved on naowh.gg, is not this character's."] = "Dein Abzeichen von Naowh Forever ist auf diesem Charakter aus: Sein Code oder der auf naowh.gg gespeicherte BattleTag gehört nicht zu diesem Charakter."
