L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = "Eine .png-, .tga- oder .blp-Datei. Mach Breite und Höhe sicherheitshalber zu Zweierpotenzen, etwa 128, 256, 512 oder 1024; ein kleines Bild mit 128 oder 256 eignet sich für ein Muster, das mit „Bild kacheln“ wiederholt wird, und „Kachelgröße“ sagt, wie breit jede Wiederholung ist. Eine .jpg liest das Spiel sehr wahrscheinlich nicht: Öffne sie und speichere sie zuerst als .png."
L["A button that invites everyone on your invite buttons."] = "Ein Knopf, der alle auf deinen Einladeknöpfen einlädt."
L["A button that invites your target."] = "Ein Knopf, der dein Ziel einlädt."
L["A color behind each bar, where it is not filled."] = "Eine Farbe hinter jeder Leiste, wo sie nicht gefüllt ist."
