L["A thin border round the window and the spell panel."] = "Ein dünner Rand um das Fenster und das Zauber-Panel."
L["A window of its own, with its own list, session and size, and a look of its own if you want one."] = "Ein eigenes Fenster mit eigener Liste, eigenem Segment und eigener Größe, auf Wunsch auch mit eigener Optik."
L["A window that says where to put a picture and what to type."] = "Ein Fenster, das erklärt, wohin ein Bild gehört und was du eingeben musst."
