L["In the game's Interface\\AddOns folder make a folder of your own, such as MyBackgrounds, and put the file in it, for instance MyBackgrounds\\panel.png. A folder of your own is not touched when add-ons are updated. Restart the game once so it finds the file."] = "Lege im Ordner Interface\\AddOns des Spiels einen eigenen Ordner an, etwa MyBackgrounds, und lege die Datei hinein, zum Beispiel MyBackgrounds\\panel.png. Ein eigener Ordner bleibt beim Aktualisieren von Addons unberührt. Starte das Spiel einmal neu, damit es die Datei findet."
L["In the Window card, under Picture, pick Your Own Picture in Image, and write the path from Interface in Custom Image, with backslashes and with the file's extension: Interface\\AddOns\\MyBackgrounds\\panel.png. Pick None or another picture in Image to go back."] = "Wähle in der Karte „Fenster“ unter „Bild“ bei „Bild“ den Eintrag „Dein eigenes Bild“ und schreibe den Pfad ab Interface in „Eigener Bildpfad“, mit Backslashes und mit der Dateiendung: Interface\\AddOns\\MyBackgrounds\\panel.png. Wähle bei „Bild“ „Keins“ oder ein anderes Bild, um zurückzugehen."
