L["The damage meter is not available"] = "Die Schadensanzeige ist nicht verfügbar"
L["The fastest way anywhere: walking, flights, boats, zeppelins, the tram, portals and your Hearthstone."] = "Der schnellste Weg überallhin: zu Fuß, per Flugroute, Schiff, Zeppelin, Tiefenbahn, Portal und mit deinem Ruhestein."
