L["Which column stands where, left to right, in each row: the name, the total, the per-second figure, the share, or another list's total for the same player. Another list's total fills in after the fight."] = "Welche Spalte wo steht, von links nach rechts in jeder Zeile: der Name, die Summe, der Wert pro Sekunde, der Anteil oder die Summe einer anderen Liste für denselben Spieler. Die Summe einer anderen Liste füllt sich nach dem Kampf."
L["Which columns a row has and where, and how numbers, shares and per-second figures are written."] = "Welche Spalten eine Zeile hat und wo, und wie Zahlen, Anteile und Werte pro Sekunde geschrieben werden."
