L["Window Width"] = "Fensterbreite"
L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Ist Verzauberkunst offen, öffnet ein Knopf „Entzaubern“ oben im Fenster ein Fenster mit jedem Gegenstand in deinen Taschen, den du entzaubern kannst: grüne, blaue und lila Waffen und Rüstungen (oder gib /naowh disenchant ein). Rechtsklicke einen Gegenstand, um dieses eine Exemplar zu behalten, oder Umschalt-Rechtsklick, um jedes Exemplar davon zu behalten, auf jedem Charakter, bis du ihn wieder rechtsklickst. „Alle entzaubern“ entzaubert den Rest nacheinander, einen Gegenstand pro Klick, weil das Spiel für jedes Entzaubern einen Klick verlangt. Ein Gegenstand, den das Spiel nicht annimmt (Fertigkeit zu niedrig), wird bis zum nächsten Neuladen übersprungen. Schließt sich bei Kampfbeginn."
L["Writes the per-second figure with /s after it."] = "Schreibt den Wert pro Sekunde mit /s dahinter."
L["Writes the time as (0:05)."] = "Schreibt die Zeit als (0:05)."
L["Writes the total and the per-second figure as one text with a bar between: 117 | 23."] = "Schreibt Summe und Wert pro Sekunde als einen Text mit einem Strich dazwischen: 117 | 23."
