L["Disabled"] = "Deaktiviert"
L["Elixirs"] = "Elixiere"
L["Enabled"] = "Aktiviert"
L["Flasks"] = "Fläschchen"
L["How Many"] = "Wie viele"
L["How many of the item to add."] = "Wie viele des Gegenstands hinzugefügt werden."
L["How many the shopping list buys."] = "Wie viele die Einkaufsliste kauft."
L["Last Used"] = "Zuletzt benutzt"
L["Learn Selected"] = "Ausgewählte lernen"
L["Lv %d"] = "St. %d"
L["No consumables to show yet."] = "Noch keine Verbrauchsgüter zum Anzeigen."
L["No item found for that. Use a link, an item ID, or the name of an item you have seen."] = "Dazu wurde kein Gegenstand gefunden. Nimm einen Link, eine Gegenstands-ID oder den Namen eines Gegenstands, den du schon gesehen hast."
L["Only for my class"] = "Nur für meine Klasse"
L["Only for My Class"] = "Nur für meine Klasse"
L["Opens your shopping list, which stays open when this window closes."] = "Öffnet deine Einkaufsliste, die offen bleibt, wenn dieses Fenster schließt."
L["Opens your shopping list beside this window."] = "Öffnet deine Einkaufsliste neben diesem Fenster."
L["Detach"] = "Abdocken"
L["Dock"] = "Andocken"
L["Lifts the Shopping List off the profession window, to drag it anywhere."] = "Löst die Einkaufsliste vom Berufsfenster, damit du sie frei verschieben kannst."
L["Puts the Shopping List back beside the profession window."] = "Setzt die Einkaufsliste wieder neben das Berufsfenster."
L["Dock Shopping List"] = "Einkaufsliste andocken"
L["Docks the Shopping List beside the profession window and moves its tabs to the left."] = "Dockt die Einkaufsliste neben dem Berufsfenster an und verschiebt seine Reiter nach links."
L["Reload UI to dock or undock the Shopping List."] = "Lade das Interface neu, um die Einkaufsliste an- oder abzudocken."
L["Other Items"] = "Andere Gegenstände"
L["Picks food, flasks, elixirs and more for your class to buy."] = "Wählt Essen, Fläschchen, Elixiere und mehr für deine Klasse zum Kaufen aus."
L["Potions"] = "Tränke"
L["Puts one more on the shopping list."] = "Setzt eins mehr auf die Einkaufsliste."
L["Puts that many of the item on the list."] = "Setzt so viele des Gegenstands auf die Liste."
L["Scrolls"] = "Rollen"
L["Shift-click an item, or type its name or ID."] = "Füge einen Gegenstand per Umschalt-Klick ein oder gib seinen Namen oder seine ID ein."
L["Shows what suits your class and level, or everything when off."] = "Zeigt, was zu deiner Klasse und Stufe passt, oder alles, wenn ausgeschaltet."
L["Takes one off."] = "Nimmt eins weg."
L["Takes one off the shopping list."] = "Nimmt eins von der Einkaufsliste."
L["Takes this item off the list."] = "Nimmt diesen Gegenstand von der Liste."
L["Turn on the Shopping List in the Professions settings first."] = "Schalte zuerst die Einkaufsliste in den Optionen der Berufe ein."
L["Weapon Enhancements"] = "Waffenverbesserungen"
L["A glow around each reminder icon, since each is a buff that is missing or running out."] = "Ein Leuchten um jedes Erinnerungssymbol, denn jedes steht für einen Buff, der fehlt oder abläuft."
L["A glow around the icon while it shows."] = "Ein Leuchten um das Symbol, solange es angezeigt wird."
L["A glow around the reminder while you have no Camp Benefits."] = "Ein Leuchten um die Erinnerung, solange du keine Lagervorteile hast."
L["A minimap button that opens %s. Saved for this computer."] = "Eine Minikarten-Schaltfläche, die %s öffnet. Wird für diesen Computer gespeichert."
L["A reminder when a weapon has no sharpening stone, weightstone or oil on it."] = "Eine Erinnerung, wenn auf einer Waffe kein Wetzstein, Gewichtsstein oder Öl liegt."
L["Beside your class trainer, the spells you can learn now, ticked, with their total and Learn Selected. Untick one to leave it."] = "Neben deinem Klassenlehrer die Zauber, die du jetzt lernen kannst, angehakt, mit ihrer Summe und der Schaltfläche Ausgewählte lernen. Nimm bei einem den Haken weg, um ihn auszulassen."
L["Click the Fire to Sit"] = "Zum Sitzen aufs Feuer klicken"
L["Click to leave it out of Learn Selected."] = "Klicke, um ihn aus der Auswahl zu nehmen."
L["Click to sit"] = "Zum Sitzen klicken"
L["click to sit"] = "zum Sitzen klicken"
L["Click to sit at the campfire."] = "Klicke, um dich ans Lagerfeuer zu setzen."
L["Counts the talents that raise a spell's healing or damage or give mana back, at the ranks you have."] = "Rechnet die Talente ein, die Heilung oder Schaden eines Zaubers erhöhen oder Mana zurückgeben, mit den Rängen, die du hast."
L["Default: the item you carry, or the kind's usual icon. Last Used: the icon of the food, flask, elixir, scroll or weapon item you used last."] = "Standard: der Gegenstand, den du dabeihast, oder das übliche Symbol der Art. Zuletzt benutzt: das Symbol des Essens, Fläschchens, Elixiers, der Rolle oder des Waffengegenstands, den du zuletzt benutzt hast."
L["Dresses the addon's windows as Naowh's own or WoW Forever's, after a reload."] = "Kleidet die Fenster des Addons wie Naowhs eigene oder wie die von WoW Forever, nach einem Neuladen."
L["Fishing %d-%d"] = "Angeln %d-%d"
L["Fishing Levels"] = "Angelfertigkeit"
L["Forever icons are in full color"] = "Forever-Symbole sind vollfarbig"
L["Glow Color"] = "Leuchtfarbe"
L["Glow Type"] = "Leuchtart"
L["Glow When Refresh Needed"] = "Leuchten, wenn Erneuern fällig ist"
L["Include My Talents"] = "Meine Talente einrechnen"
L["Learn Selected (%d)  %s"] = "Ausgewählte lernen (%d)  %s"
L["Every module enabled for the full Naowh Forever experience. Great if you're a power user with addons and want all the bells and whistles."] = "Jedes Modul aktiviert, für das volle Erlebnis von Naowh Forever. Ideal, wenn du viel mit Addons machst und keine Funktion missen willst."
L["Looting, Vendors, Mail & Auction House"] = "Plündern, Händler, Post & Auktionshaus"
L["Looting, selling and repairing at vendors, auction house prices, and mail with your alts."] = "Plündern, Verkaufen und Reparieren bei Händlern, Auktionshauspreise und Post mit deinen Twinks."
L["Recommended turns on the essentials and nothing that spoils the game; Everything Enabled turns on every module."] = "Recommended schaltet das Wesentliche ein und nichts, was dir das Spiel verdirbt; Everything Enabled schaltet jedes Modul ein."
L["Naowh's Forge, Macros' own window: your macros and their editor, the ones kept current, and the Library."] = "Naowh's Forge, das eigene Fenster von Makros: deine Makros und ihr Editor, die aktuell gehaltenen und die Bibliothek."
L["Near a campfire the reminder's fire lights up: click it to sit down."] = "In der Nähe eines Lagerfeuers leuchtet das Feuer der Erinnerung auf: Klicke darauf, um dich zu setzen."
L["Needs Show Refresh Reminder"] = "Benötigt: Erinnerung zum Erneuern anzeigen"
L["Needs the glow on"] = "Benötigt das Leuchten"
L["No weapon master is known for your faction."] = "Für deine Fraktion ist kein Waffenmeister bekannt."
L["On: any flask, elixir or buff food in your bags reminds you, listed or not; off: even with none."] = "An: Jedes Fläschchen, Elixier oder Buff-Essen in deinen Taschen erinnert dich, ob gelistet oder nicht; aus: auch ohne Vorrat."
L["Open Discovery"] = "Entdeckungen öffnen"
L["A streamlined setup with the essentials enabled and nothing that spoils the game. You can add more modules whenever you like. Perfect if you're a Classic player and don't want to use a lot of addons."] = "Eine schlanke Einrichtung mit dem Wesentlichen und nichts, was dir das Spiel verdirbt. Weitere Module kannst du jederzeit hinzufügen. Perfekt, wenn du Classic spielst und nicht viele Addons nutzen willst."
L["Pixel Glow runs lines around the icon; Standard Glow is the game's own button glow."] = "Pixelleuchten lässt Linien um das Symbol laufen; Standardleuchten ist das Schaltflächenleuchten des Spiels."
L["Pixel Glow"] = "Pixelleuchten"
L["Press this key to open Discovery's window, and again to close it."] = "Drücke diese Taste, um das Fenster von Entdeckungen zu öffnen, und erneut, um es zu schließen."
L["Press this key to open the Training Planner, and again to close it."] = "Drücke diese Taste, um den Ausbildungsplaner zu öffnen, und erneut, um ihn zu schließen."
L["Puts the bar back above Buff Reminders, anchored to them."] = "Setzt die Leiste wieder über die Buff-Erinnerungen und verankert sie dort."
L["The group was not disbanded. Open Disband and click Yes again."] = "Die Gruppe wurde nicht aufgelöst. Öffne Auflösen und klicke erneut auf Ja."
L["Requires quest"] = "Benötigt Quest"
L["Requires: %s"] = "Benötigt: %s"
L["Select All"] = "Alle"
L["Shift-click to link it. Click for a waypoint to where it is taught."] = "Umschalt-Klick, um sie zu verlinken. Klicke für einen Wegpunkt dorthin, wo sie gelehrt wird."
L["Show Activity Bar"] = "Aktivitätsleiste anzeigen"
L["Show Icons"] = "Symbole anzeigen"
L["Shows the Fishing skill a zone needs when you hover it on the world map."] = "Zeigt die Angelfertigkeit, die ein Gebiet braucht, wenn du auf der Weltkarte mit der Maus darüberfährst."
L["Speed"] = "Tempo"
L["Standard Glow"] = "Standardleuchten"
L["Skipped by the build you follow."] = "Vom Build, dem du folgst, ausgelassen."
L["Your build"] = "Dein Build"
L["SPELLS TO SKIP"] = "AUSZULASSENDE ZAUBER"
L["Checked spells are left out when you train; everything else is trained"] = "Angehakte Zauber werden beim Lernen ausgelassen; alles andere wird gelernt"
L[", skipping %d"] = ", %d ausgelassen"
L["Taught by a weapon master: %s."] = "Gelehrt von einem Waffenmeister: %s."
L["Taught by your class trainer."] = "Gelehrt von deinem Klassenlehrer."
L["WEAPON SKILLS"] = "WAFFENFERTIGKEITEN"
L["Click one for a waypoint to where it is taught"] = "Klicke auf eine für einen Wegpunkt dorthin, wo sie gelehrt wird"
L["The key that opens Discovery's window."] = "Die Taste, die das Fenster von Entdeckungen öffnet."
L["The key that opens the Training Planner."] = "Die Taste, die den Ausbildungsplaner öffnet."
L["Turn on Blessings on a paladin"] = "Segen auf einem Paladin einschalten"
L["Weapon Enhancement Reminder"] = "Erinnerung an Waffenverbesserung"
L["What the bar offers to add, and the smart buttons that pick your best item."] = "Was die Leiste zum Hinzufügen anbietet, und die Smart-Schaltflächen, die deinen besten Gegenstand wählen."
L["Smart Buttons"] = "Smart-Schaltflächen"
L["Food & Drink Buttons"] = "Schaltflächen für Speis & Trank"
L["Your best food and drink, conjured first; the Food & Drink Bar steps aside."] = "Dein bestes Essen und Trinken, herbeigezaubertes zuerst; die Leiste für Speis & Trank macht Platz."
L["Best Food"] = "Bestes Essen"
L["Best Drink"] = "Bestes Getränk"
L["A smart button already covers some of these, or they need mana: %s. Add them anyway?"] = "Eine Smart-Schaltfläche deckt einige davon schon ab, oder sie brauchen Mana: %s. Trotzdem hinzufügen?"
L["The food button already uses your best food. Add %s too?"] = "Die Essensschaltfläche nutzt schon dein bestes Essen. %s trotzdem hinzufügen?"
L["The drink button already uses your best drink. Add %s too?"] = "Die Getränkeschaltfläche nutzt schon dein bestes Getränk. %s trotzdem hinzufügen?"
L["The Food & Drink buttons are on the bar. Take them off to use %s."] = "Die Schaltflächen für Speis & Trank sind auf der Leiste. Nimm sie herunter, um %s zu nutzen."
L["%s is on the bar. Take it off to use the Food & Drink buttons."] = "%s ist auf der Leiste. Nimm es herunter, um die Schaltflächen für Speis & Trank zu nutzen."
L["The Food & Drink buttons are on the bar"] = "Die Schaltflächen für Speis & Trank sind auf der Leiste"
L["%s is on the bar"] = "%s ist auf der Leiste"
L["Its buttons are on the Consumable Bar"] = "Ihre Schaltflächen sind auf der Verbrauchsleiste"
L["Where the bar sits: above Buff Reminders at first, then on another element, a unit frame or where you drag it."] = "Wo die Leiste sitzt: zuerst über den Buff-Erinnerungen, dann an einem anderen Element, einem Einheitenfenster oder dort, wohin du sie ziehst."
L["WoW Forever's own windows, in metal and stone."] = "Die eigenen Fenster von WoW Forever, in Metall und Stein."
L["Your modules were changed to match your profile. Reload now?"] = "Deine Module wurden an dein Profil angepasst. Jetzt neu laden?"
L["Your class buffs when they are missing or about to run out."] = "Deine Klassenbuffs, wenn sie fehlen oder bald ablaufen."
L["Put the game's waypoint on the dock, flight master or goal, not on every bend of the walk there."] = "Setzt den Wegpunkt des Spiels auf den Anleger, den Flugmeister oder das Ziel, nicht auf jede Biegung des Wegs dorthin."
L["Waypoint Only Where Steps End"] = "Wegpunkt nur am Ende eines Schritts"
L["Hunter Ammo"] = "Jägermunition"
L["Hunter Ammo Reminder"] = "Erinnerung an Jägermunition"
L["Remind Me When Ammo Falls To"] = "Erinnern ab Munitionsmenge"
L["Reminds you about your equipped ammo at its own amount, not the carry target."] = "Erinnert dich an deine angelegte Munition mit eigener Menge, nicht mit dem Munitionsvorrat."
L["Reminds at or below this many equipped arrows or shot across all bag stacks."] = "Erinnert, sobald du über alle Taschenstapel hinweg nur noch so viele Pfeile oder Kugeln der angelegten Sorte hast."
L["%s changes the same game settings as Glimmer, so they undo each other. Disable %s?"] = "%s ändert dieselben Spieleinstellungen wie Schimmer, sodass sie sich gegenseitig aufheben. %s deaktivieren?"
L["%s will be off after a reload. Reload now?"] = "%s ist nach dem Neuladen aus. Jetzt neu laden?"
