L["Dim while the object is too far to use."] = "Gedimmt, solange das Objekt zum Benutzen zu weit weg ist."
L["In Reach"] = "In Reichweite"
L["Bright once you can gather, loot or use it."] = "Hell, sobald du es sammeln, plündern oder benutzen kannst."
L["Too Low"] = "Zu niedrig"
L["Grey when your skill is too low for it."] = "Grau, wenn deine Fertigkeit dafür zu niedrig ist."
L["Effect"] = "Effekt"
L["Brightness"] = "Helligkeit"
