L["Color herbs and ore by your chance of a skill-up, red when your skill is too low."] = "Färbt Kräuter und Erz nach deiner Chance auf eine Steigerung, rot, wenn deine Fertigkeit zu niedrig ist."
L["Show Skill and Quest Line"] = "Fertigkeits- und Questzeile anzeigen"
L["A line under the name: the skill-up chance, or what the quest still needs."] = "Eine Zeile unter dem Namen: die Chance auf eine Steigerung oder was die Quest noch braucht."
L["Objects"] = "Objekte"
L["What lights up, each with its own effect and color if you like."] = "Was aufleuchtet, auf Wunsch jeweils mit eigenem Effekt und eigener Farbe."
L["When to Hide"] = "Wann ausblenden"
L["Glimmer always rests in combat, since the game locks these settings there."] = "Schimmer pausiert im Kampf immer, weil das Spiel diese Einstellungen dort sperrt."
L["In Dungeons and Raids"] = "In Dungeons und Raids"
L["On Nodes Your Skill Is Too Low For"] = "Bei Vorkommen über deiner Fertigkeit"
L["Leave them dark instead of grey."] = "Lässt sie dunkel statt grau."
L["Detection"] = "Erkennung"
L["The one object the game would interact with is the one that lights up."] = "Es leuchtet genau das Objekt auf, mit dem das Spiel interagieren würde."
L["How far away the game may pick an object to light up."] = "Wie weit entfernt das Spiel ein Objekt zum Aufleuchten wählen darf."
L["Look For Objects"] = "Objekte suchen"
L["Only Name What Glimmer Lights"] = "Nur Leuchtendes benennen"
L["No soft target name on NPCs, mailboxes and doors."] = "Kein Name durch weiches Anvisieren bei NSCs, Briefkästen und Türen."
L["Interact Key"] = "Interaktionstaste"
L["Gathers, loots or uses the lit object once it is in reach."] = "Sammelt, plündert oder benutzt das leuchtende Objekt, sobald es in Reichweite ist."
