L["Glimmer"] = "Schimmer"
L["Herbs, ore, chests and quest objects light up as you walk up to them."] = "Kräuter, Erz, Truhen und Questobjekte leuchten auf, wenn du dich ihnen näherst."
L["Gathered %d times, last %s."] = "%d-mal gesammelt, zuletzt %s."
L["Turn on Gathered Herbs and Ore"] = "Gesammelte Kräuter und Erze einschalten"
L["Minimap Icons"] = "Minikartensymbole"
L["Every spot herbs and ore grow near you, on the minimap, ringed in its skill-up color. With Find Herbs or Find Minerals on, the ring is left open and the game's own dot shows in it while the node is up."] = "Jede Stelle in deiner Nähe, an der Kräuter und Erz wachsen, auf der Minikarte, umrandet in ihrer Steigerungsfarbe. Mit Kräutersuche oder Mineraliensuche bleibt der Ring offen, und der Punkt des Spiels zeigt sich darin, solange das Vorkommen da ist."
L["Only My Professions"] = "Nur meine Berufe"
L["Only herbs if you are an herbalist, only ore if you are a miner."] = "Kräuter nur, wenn du Kräuterkunde hast, Erz nur, wenn du Bergbau hast."
L["Gathered Herbs and Ore"] = "Gesammelte Kräuter und Erze"
L["Every herb and vein you gather, on the world map; click one for a waypoint."] = "Jedes Kraut und jede Ader, die du sammelst, auf der Weltkarte; ein Klick darauf setzt einen Wegpunkt."
L["Gathered Pin Size"] = "Größe der Sammel-Pins"
L["Gathered on the Map"] = "Gesammeltes auf der Karte"
L["Glimmer notes every herb and vein you gather, so you can find them again."] = "Schimmer merkt sich jedes Kraut und jede Ader, die du sammelst, damit du sie wiederfindest."
