L["HOW TO PLAY\n\nSET UP A SESSION\nEnter the pool in gold-and-silver format: an integer followed by \"g\", then an integer followed by \"s\" (for example, 10g50s). One gold is 100 silver, so 10g50s is 1,050 silver. All roll limits use the pool's total silver value. Party and Raid chat are supported; choose the channel your group is using. Both pool components must be whole numbers.\n\nSelect New Game to announce the session. Players, including the host, join by saying the configured join word in the selected chat. They can leave the lobby by saying the leave word. The host can use Last Call to remind the group, then select Start Rolling once at least two players have joined.\n\nCLASSIC\nWhen the host selects Start Rolling, chat announces that everyone can roll and gives the roll limit. Every joined player rolls from 1 to the pool's total silver value using /roll. With a 10g50s pool, each player rolls from 1 to 1,050. Use Announce Rolls to remind players who still need to roll and show the roll range.\n\nWhen everyone has rolled, the player with the lowest roll pays the player with the highest roll the difference between those original rolls. The difference is silver and is announced in gold-and-silver format (for example, 50 silver is shown as 0g50s). If the highest or lowest roll is tied, only the players tied at that extreme reroll to decide that side's winner or loser. The original high and low rolls determine the amount, even if a tie-break roll changes the order. If every player rolls the same number, nobody pays and everyone rolls again.\n\nDEATHROLL\nAfter the host starts the game, two joined players are selected at random. Gamble announces the selected players, then announces which one was randomly chosen to roll first.\n\nThe first player rolls from 1 to the pool's total silver value. With a 10g50s pool, the first roll is from 1 to 1,050. The two selected players then alternate: after each roll, the next player rolls from 1 to the value just rolled. Use Announce Rolls to identify whose turn it is and the current roll range. The first player to roll 1 loses; the other player wins the pool, announced in gold-and-silver format.\n\nENDING A SESSION\nThe host can select Cancel Session at any time before the session completes. The cancellation is announced in chat and the session ends for everyone. Completed sessions cannot be cancelled.\n\nGamble only announces results; it does not transfer gold. Players settle any announced amount themselves."] = "SO WIRD GESPIELT\n\nEINE RUNDE EINRICHTEN\nGib den Einsatz im Gold-und-Silber-Format ein: eine ganze Zahl gefolgt von \"g\", dann eine ganze Zahl gefolgt von \"s\" (zum Beispiel 10g50s). Ein Gold sind 100 Silber, also sind 10g50s 1.050 Silber. Alle Würfelgrenzen richten sich nach dem gesamten Silberwert des Einsatzes. Gruppen- und Raidchat werden unterstützt; wähle den Kanal, den deine Gruppe nutzt. Beide Teile des Einsatzes müssen ganze Zahlen sein.\n\nWähle Neues Spiel, um die Runde anzukündigen. Spieler, auch der Spielleiter, treten bei, indem sie das eingestellte Beitrittswort im gewählten Chat sagen. Mit dem Austrittswort verlassen sie die Runde wieder. Der Spielleiter kann mit Letzter Aufruf die Gruppe erinnern und wählt dann Los würfeln, sobald mindestens zwei Spieler beigetreten sind.\n\nCLASSIC\nWählt der Spielleiter Los würfeln, sagt der Chat an, dass alle würfeln dürfen, und nennt die Würfelgrenze. Jeder beigetretene Spieler würfelt mit /roll von 1 bis zum gesamten Silberwert des Einsatzes. Bei einem Einsatz von 10g50s würfelt jeder von 1 bis 1.050. Mit Würfe ansagen erinnerst du Spieler, die noch würfeln müssen, und zeigst den Würfelbereich.\n\nHaben alle gewürfelt, zahlt der Spieler mit dem niedrigsten Wurf dem Spieler mit dem höchsten Wurf die Differenz dieser ursprünglichen Würfe. Die Differenz ist in Silber und wird im Gold-und-Silber-Format angesagt (zum Beispiel erscheinen 50 Silber als 0g50s). Gibt es beim höchsten oder niedrigsten Wurf einen Gleichstand, würfeln nur die Spieler mit diesem Gleichstand neu, um Gewinner oder Verlierer dieser Seite zu bestimmen. Der Betrag ergibt sich aus den ursprünglichen höchsten und niedrigsten Würfen, auch wenn ein Stechen die Reihenfolge ändert. Würfeln alle dieselbe Zahl, zahlt niemand und alle würfeln erneut.\n\nDEATHROLL\nNachdem der Spielleiter das Spiel gestartet hat, werden zwei beigetretene Spieler zufällig gewählt. Würfelspiel sagt die gewählten Spieler an und danach, wer zufällig als Erster würfelt.\n\nDer erste Spieler würfelt von 1 bis zum gesamten Silberwert des Einsatzes. Bei einem Einsatz von 10g50s geht der erste Wurf von 1 bis 1.050. Danach würfeln die beiden abwechselnd: Nach jedem Wurf würfelt der nächste Spieler von 1 bis zum gerade gewürfelten Wert. Mit Würfe ansagen zeigst du, wer an der Reihe ist und welcher Würfelbereich gilt. Wer zuerst eine 1 würfelt, verliert; der andere Spieler gewinnt den Einsatz, angesagt im Gold-und-Silber-Format.\n\nEINE RUNDE BEENDEN\nDer Spielleiter kann jederzeit vor dem Ende Abbrechen wählen. Der Abbruch wird im Chat angesagt, und die Runde endet für alle. Beendete Runden lassen sich nicht abbrechen.\n\nWürfelspiel sagt nur Ergebnisse an; es überweist kein Gold. Die Spieler begleichen angesagte Beträge selbst."
