L["Add an item ID, drag an item onto its section, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Füge eine Gegenstands-ID hinzu, ziehe einen Gegenstand auf seinen Abschnitt oder importiere eine Liste. Bei Essen zählt jeder Satt-Buff, bei anderen Gegenständen ihr eigener Buff; füge Buff-Zauber-IDs nur für einen Gegenstand hinzu, der einen anderen gibt. Nichts wird automatisch hinzugefügt. Fahre mit der Maus über eine Erinnerung, um einen eingerichteten Gegenstand aus deinen Taschen zu wählen. Erinnerungen pausieren im Kampf; Gegenstandsmenüs funktionieren außerhalb des Kampfes. Wann und wo sie erscheinen, steht unter AuraBuffs > Optionen."
L["%s is already in %s."] = "%s ist schon in %s."
L["%s has no buff of its own: add it by ID with its buff spell IDs."] = "%s hat keinen eigenen Buff: Füge ihn per ID mit seinen Buff-Zauber-IDs hinzu."
L["The list is full at %d consumables."] = "Die Liste ist mit %d Verbrauchsgütern voll."
L["Drag an item here, or add it by ID"] = "Ziehe einen Gegenstand hierher oder füge ihn per ID hinzu"
