L["Your keys as they are now, coloured by what they press."] = "Deine Tasten, wie sie jetzt sind, gefärbt nach dem, was sie auslösen."
L["This set keeps no keybinds: these are your keys as they are now."] = "Dieses Set enthält keine Tastenbelegungen: Das sind deine Tasten, wie sie jetzt sind."
L["Other commands"] = "Andere Befehle"
L["Free"] = "Frei"
L["Changes on import"] = "Ändert sich"
L["On this character now: %s"] = "Auf diesem Charakter jetzt: %s"
L["FREE NEAR WASD"] = "FREI RUND UM WASD"
L["None: every key near WASD is taken."] = "Keine: Jede Taste rund um WASD ist belegt."
L["ON NO KEY"] = "AUF KEINER TASTE"
L["Every action on your main bars has a key."] = "Jede Aktion auf deinen Hauptleisten hat eine Taste."
L["No Modifier"] = "Ohne"
L["Load a Bar Set"] = "Leistenset laden"
L["%s (on your bars)"] = "%s (auf deinen Leisten)"
L["Save Bars into %s"] = "Leisten in %s sichern"
L["Open Bar Sets"] = "Leistensets öffnen"
L["in battlegrounds"] = "in Schlachtfeldern"
L["at level %d"] = "auf Stufe %d"
L["Load on Its Own"] = "Von selbst laden"
L["Entering a Dungeon or Raid"] = "Beim Betreten eines Dungeons oder Raids"
L["Loads this set when you enter a dungeon or raid."] = "Lädt dieses Set, wenn du einen Dungeon oder Raid betrittst."
L["Joining a Battleground"] = "Beim Beitritt zu einem Schlachtfeld"
L["Loads this set when you join a battleground."] = "Lädt dieses Set, wenn du einem Schlachtfeld beitrittst."
L["Put Back on Leaving"] = "Beim Verlassen zurückholen"
L["When you leave, the bars you had before the instance come back."] = "Wenn du gehst, kommen die Leisten von vor der Instanz zurück."
L["On Reaching a Level"] = "Beim Erreichen einer Stufe"
L["Loads this set once, at the level below."] = "Lädt dieses Set einmal, auf der unten eingestellten Stufe."
L["The level On Reaching a Level loads its set at."] = "Die Stufe, auf der „Beim Erreichen einer Stufe“ sein Set lädt."
L["Right-click for a quick menu."] = "Rechtsklick öffnet ein Schnellmenü."
L["Your bars can be changed out of combat."] = "Deine Leisten lassen sich nur außerhalb des Kampfes ändern."
L["Upgraded %d spells on your bars to your best rank."] = "%d Zauber auf deinen Leisten auf deinen besten Rang angehoben."
L["Upgraded 1 spell on your bars to your best rank."] = "1 Zauber auf deinen Leisten auf deinen besten Rang angehoben."
L["Set icon"] = "Set-Symbol"
L["Pick one from your bars. Auto shows the set's first spell."] = "Wähle eins von deinen Leisten. Auto zeigt den ersten Zauber des Sets."
L["+ Tag"] = "+ Neu"
L["A tag for this set, such as Dungeon or PvP"] = "Ein Kürzel für dieses Set, etwa Dungeon oder PvP"
L["Click to take this tag off."] = "Klicke, um dieses Kürzel zu entfernen."
L["No saved set has this tag."] = "Kein gespeichertes Set hat dieses Kürzel."
L["ON YOUR BARS"] = "AUF DEINEN LEISTEN"
L["BAR CHECK"] = "LEISTEN-CHECK"
L["%d spells below your best rank"] = "%d Zauber unter deinem besten Rang"
L["1 spell below your best rank"] = "1 Zauber unter deinem besten Rang"
L["Upgrade All"] = "Alle anheben"
L["Leave as Is"] = "So lassen"
L["Keeps these ranks, for downranking, and stops asking about them."] = "Behält diese Ränge fürs Downranking und fragt nicht mehr danach."
L["NEW SPELLS"] = "NEUE ZAUBER"
L["%d spells you know are on no bar"] = "%d bekannte Zauber liegen auf keiner Leiste"
L["1 spell you know is on no bar"] = "1 bekannter Zauber liegt auf keiner Leiste"
L["Drag one onto your bars."] = "Zieh einen auf deine Leisten."
L["Hide These"] = "Ausblenden"
L["Stops listing these spells as new."] = "Listet diese Zauber nicht mehr als neu."
L["Before putting back a backup"] = "Vor dem Einspielen einer Sicherung"
L["Before importing %s"] = "Vor dem Import von %s"
L["Backups can be put back out of combat."] = "Sicherungen lassen sich nur außerhalb des Kampfes einspielen."
L["Put back your bars from %s: %s."] = "Deine Leisten vom %s wieder eingespielt: %s."
L["There is no import to undo."] = "Es gibt keinen Import, der sich rückgängig machen ließe."
L["The set keeps this slot empty, so the import takes this off."] = "Das Set lässt diesen Platz leer, also nimmt der Import das hier weg."
L["Something else is here now: the import swaps it."] = "Hier liegt gerade etwas anderes: Der Import tauscht es aus."
L["Import %d changes"] = "Importieren (%d)"
L["Import 1 change"] = "Importieren (1)"
L["Actions"] = "Aktionen"
L["Every key already does what the set binds."] = "Jede Taste tut schon, was das Set belegt."
L["nothing"] = "nichts"
L["Off: your keys stay as they are."] = "Aus: Deine Tasten bleiben, wie sie sind."
L["%s is on your bars. Your bars from before it are kept as a backup."] = "%s liegt auf deinen Leisten. Deine Leisten von vorher bleiben als Sicherung erhalten."
L["Undo Import"] = "Rückgängig"
L["Backups"] = "Sicherungen"
L["Put Back"] = "Einspielen"
L["Save as Set"] = "Set anlegen"
L["Put back your bars, keybinds and macros from %s?"] = "Deine Leisten, Tastenbelegungen und Makros vom %s wieder einspielen?"
L["Name for the set made from this backup"] = "Name für das Set aus dieser Sicherung"
L[" Sold by vendors: %s"] = " Wird von Händlern verkauft: %s"
L["%s is no longer part of Naowh Forever: delete its old folder from your AddOns folder."] = "%s gehört nicht mehr zu Naowh Forever: Lösche seinen alten Ordner aus deinem AddOns-Ordner."
L["A ! in its own color for quest givers with a dungeon or raid quest."] = "Ein ! in eigener Farbe für Questgeber mit einer Dungeon- oder Raidquest."
L["Color Dungeon Quests"] = "Dungeonquests einfärben"
L["Dungeon Quest Color"] = "Farbe der Dungeonquests"
L["Left-click turns it on, and right-click hides it until you change area."] = "Linksklick schaltet es ein, Rechtsklick blendet es aus, bis du das Gebiet wechselst."
L["A name without its last name gets it the next time you log in on that character."] = "Ein Name ohne Nachnamen bekommt ihn, sobald du dich das nächste Mal mit diesem Charakter einloggst."
L["Raid Buffs to Remind"] = "Raidbuffs mit Erinnerung"
L["Personal Buffs to Remind"] = "Persönliche Buffs mit Erinnerung"
L["Save your bars here, or with /nf bars save and a name."] = "Sichere deine Leisten hier oder mit /nf bars save und einem Namen."
L["Shows an icon for each racial or class tracking you have not turned on."] = "Zeigt ein Symbol für jedes Aufspüren deines Volks oder deiner Klasse, das du nicht eingeschaltet hast."
L["Reminds you to turn on tracking."] = "Erinnert dich daran, Aufspüren einzuschalten."
L["Reminds you to turn on your race's tracking."] = "Erinnert dich daran, das Aufspüren deines Volks einzuschalten."
L["Reminds you to turn on your class's tracking."] = "Erinnert dich daran, das Aufspüren deiner Klasse einzuschalten."
L["Reminds you while this tracking is off."] = "Erinnert dich, solange dieses Aufspüren aus ist."
L["Also reminds you inside instances."] = "Erinnert dich auch in Instanzen."
L["Racial Tracking"] = "Aufspüren des Volks"
L["Class Tracking"] = "Aufspüren der Klasse"
L["Needs Racial Tracking"] = "Benötigt: Aufspüren des Volks"
L["Needs Class Tracking"] = "Benötigt: Aufspüren der Klasse"
L["Racial and Class Tracking"] = "Aufspüren von Volk und Klasse"
L["Racial and Class Tracking is off"] = "Aufspüren von Volk und Klasse ist aus"
L["No tracking selected"] = "Kein Aufspüren gewählt"
L["Treasure"] = "Schätze"
L["Beasts"] = "Wildtiere"
L["Humanoids"] = "Humanoide"
L["Undead"] = "Untote"
L["Elementals"] = "Elementare"
L["Demons"] = "Dämonen"
L["Giants"] = "Riesen"
L["Dragonkin"] = "Drachkin"
L["The color of the ! for dungeon and raid quests."] = "Die Farbe des ! für Dungeon- und Raidquests."
L["This character last used %s. Import any set here, out of combat."] = "Dieser Charakter hat zuletzt %s genutzt. Importiere hier ein beliebiges Set, außerhalb des Kampfes."
L["Track %s"] = "%s aufspüren"
L["Turn on Color Dungeon Quests"] = "„Dungeonquests einfärben“ einschalten"
L["What a saved set brings back when you import it. Sets are saved and imported from the Bar Sets tab, out of combat."] = "Was ein gespeichertes Set beim Import zurückbringt. Sets werden im Reiter Leistensets gespeichert und importiert, außerhalb des Kampfes."
L["What shows while you know a tracking but have not turned it on."] = "Was erscheint, solange du ein Aufspüren kennst, es aber nicht eingeschaltet hast."
L["Forms"] = "Gestalten"
L["Stance Bar"] = "Haltungsleiste"
L["Enable Interact Key is off in the game's Controls settings, so nothing lights up."] = "Die Interaktionstaste ist in den Steuerungsoptionen des Spiels aus, deshalb leuchtet nichts auf."
L["Hide in the World at Level 60"] = "Auf Stufe 60 in der Welt ausblenden"
L["At level 60, consumable reminders stay out of the open world."] = "Auf Stufe 60 erscheinen Erinnerungen an Verbrauchsgüter nicht in der offenen Welt."
L["At level 60, raid buff reminders stay out of the open world."] = "Auf Stufe 60 erscheinen Raidbuff-Erinnerungen nicht in der offenen Welt."
L["At level 60, personal buff reminders stay out of the open world."] = "Auf Stufe 60 erscheinen Erinnerungen an persönliche Buffs nicht in der offenen Welt."
L["With the Gamepad interface style, the game's own recipe window is used."] = "Mit dem Gamepad-Oberflächenstil wird das spieleigene Rezeptfenster genutzt."
L["%d %b %H:%M"] = "%d.%m. %H:%M"
L["Show on All Characters"] = "Auf allen Charakteren anzeigen"
L["Shows detailed deal tooltips on characters without Enchanting."] = "Zeigt ausführliche Angebots-Tooltips auch auf Charakteren ohne Verzauberkunst."
